COURSE.add({
  id: 'm02', order: 2, icon: '☁️',
  title: { en: 'AWS basics for AI developers', he: 'יסודות AWS למפתחי AI' },
  summary: { en: 'Only the AWS you really need for GenAI: accounts, Regions, IAM, credentials, and the services around Bedrock.', he: 'רק ה-AWS שבאמת צריך ל-GenAI: חשבונות, Regions, IAM, credentials והשירותים שמסביב ל-Bedrock.' },
  glossary: [
    { term: 'Account', aka: ['AWS account'], en: 'A container for your AWS resources, users and bill. It has a 12-digit ID. Companies use many accounts (dev, staging, prod).', he: 'מכל שמחזיק את המשאבים, המשתמשים והחשבונית שלך ב-AWS. יש לו מזהה של 12 ספרות. חברות משתמשות בהרבה חשבונות (dev, staging, prod).' },
    { term: 'Region', aka: ['Regions'], en: 'A geographic location with its own AWS data centers, such as `us-east-1`. Most resources live in exactly one Region.', he: 'מיקום גאוגרפי עם מרכזי נתונים משלו של AWS, למשל `us-east-1`. רוב המשאבים חיים ב-Region אחד בדיוק.' },
    { term: 'CLI', aka: ['AWS CLI'], en: 'Command Line Interface. The `aws` command that calls AWS from a terminal.', he: 'Command Line Interface. הפקודה `aws` שקוראת ל-AWS מתוך טרמינל.' },
    { term: 'SDK', aka: ['boto3'], en: 'A code library that calls AWS for you. The Python SDK is called boto3.', he: 'ספריית קוד שקוראת ל-AWS בשבילך. ה-SDK של Python נקרא boto3.' },
    { term: 'ARN', aka: ['ARNs', 'Amazon Resource Name'], en: 'Amazon Resource Name. The full unique name of one resource, like `arn:aws:s3:::my-bucket`. Policies point at resources by ARN.', he: 'Amazon Resource Name. השם המלא והייחודי של משאב אחד, למשל `arn:aws:s3:::my-bucket`. policies מצביעות על משאבים לפי ARN.' },
    { term: 'IAM', aka: ['Identity and Access Management'], en: 'Identity and Access Management. The AWS service that decides who may do what on which resource.', he: 'Identity and Access Management. השירות של AWS שמחליט מי רשאי לעשות מה על איזה משאב.' },
    { term: 'Principal', en: 'The identity that makes an API call: a user, a role, or an AWS service.', he: 'הזהות שמבצעת קריאת API: משתמש, role או שירות של AWS.' },
    { term: 'IAM user', en: 'A permanent identity with long-term credentials (password, access keys). Mostly avoided today.', he: 'זהות קבועה עם credentials ארוכי-טווח (סיסמה, access keys). היום בעיקר נמנעים ממנה.' },
    { term: 'IAM role', aka: ['role', 'roles'], en: 'An identity with no permanent credentials. A person or a service "assumes" it and gets temporary credentials.', he: 'זהות בלי credentials קבועים. אדם או שירות "לוקח" אותה (assume) ומקבל credentials זמניים.' },
    { term: 'Policy', aka: ['policies', 'IAM policy'], en: 'A JSON document that lists permissions: Effect (Allow or Deny), Action, Resource.', he: 'מסמך JSON שמפרט הרשאות: Effect (Allow או Deny), Action, Resource.' },
    { term: 'Least privilege', en: 'Give an identity only the permissions it needs for its job, and nothing more.', he: 'לתת לזהות רק את ההרשאות שהיא צריכה לעבודה שלה, ולא יותר.' },
    { term: 'Explicit deny', en: 'A policy statement with `"Effect": "Deny"`. It always wins over any Allow.', he: 'משפט ב-policy עם `"Effect": "Deny"`. הוא תמיד מנצח כל Allow.' },
    { term: 'AccessDeniedException', aka: ['AccessDenied'], en: 'The error (HTTP 403) you get when IAM does not allow the call.', he: 'השגיאה (HTTP 403) שמקבלים כש-IAM לא מרשה את הקריאה.' },
    { term: 'Trust policy', en: 'The policy on a role that says who is allowed to assume it.', he: 'ה-policy על role שאומרת מי רשאי לקחת אותו (assume).' },
    { term: 'STS', aka: ['AssumeRole', 'Security Token Service'], en: 'Security Token Service. It hands out temporary credentials, for example when a role is assumed.', he: 'Security Token Service. מחלק credentials זמניים, למשל כשלוקחים role.' },
    { term: 'Access key', aka: ['access keys'], en: 'A long-term credential pair: an access key ID and a secret access key. If it leaks, anyone can act as you.', he: 'זוג credentials ארוך-טווח: access key ID ו-secret access key. אם הוא דולף, כל אחד יכול לפעול בשמך.' },
    { term: 'Temporary credentials', en: 'An access key, a secret and a session token that expire after minutes or hours.', he: 'access key, secret ו-session token שפג תוקפם אחרי דקות או שעות.' },
    { term: 'IAM Identity Center', aka: ['SSO', 'Identity Center'], en: 'The AWS single sign-on service. People log in once and get temporary credentials for a role in an account.', he: 'שירות ה-single sign-on של AWS. אנשים מתחברים פעם אחת ומקבלים credentials זמניים ל-role בחשבון.' },
    { term: 'Profile', aka: ['profiles'], en: 'A named set of settings (credentials source, Region) in `~/.aws/config`, chosen with `--profile` or `AWS_PROFILE`.', he: 'קבוצת הגדרות עם שם (מקור credentials, Region) בקובץ `~/.aws/config`, שבוחרים עם `--profile` או `AWS_PROFILE`.' },
    { term: 'SigV4', aka: ['Signature Version 4'], en: 'The standard AWS way of signing every request with your credentials. The SDK and CLI do it for you.', he: 'הדרך הסטנדרטית של AWS לחתום על כל בקשה עם ה-credentials שלך. ה-SDK וה-CLI עושים את זה בשבילך.' },
    { term: 'Bedrock API key', aka: ['API key', 'API keys'], en: 'A bearer token (short-term or long-term) that you send to Bedrock instead of signing requests with AWS credentials.', he: 'bearer token (קצר-טווח או ארוך-טווח) ששולחים ל-Bedrock במקום לחתום על בקשות עם credentials של AWS.' },
    { term: 'Managed policy', aka: ['AWS managed policy'], en: 'A ready-made policy written and updated by AWS, such as `AmazonBedrockFullAccess`.', he: 'policy מוכנה ש-AWS כותבת ומעדכנת, למשל `AmazonBedrockFullAccess`.' },
    { term: 'SCP', aka: ['Service control policy'], en: 'Service control policy. A limit set at the organization level on what any identity in an account can do.', he: 'Service control policy. מגבלה ברמת הארגון על מה שכל זהות בחשבון יכולה לעשות.' },
    { term: 'Shared responsibility model', aka: ['shared responsibility'], en: 'AWS secures the cloud itself. You secure what you build and configure in it.', he: 'AWS מאבטחת את הענן עצמו. אתה מאבטח את מה שאתה בונה ומגדיר בתוכו.' },
    { term: 'S3', aka: ['bucket', 'buckets', 'Amazon S3'], en: 'Simple Storage Service. File storage. Files are "objects" inside a "bucket".', he: 'Simple Storage Service. אחסון קבצים. הקבצים הם "objects" בתוך "bucket".' },
    { term: 'Lambda', aka: ['AWS Lambda', 'Lambda function'], en: 'A service that runs your function when something calls it. No server to manage, you pay per run.', he: 'שירות שמריץ את הפונקציה שלך כשמשהו קורא לה. אין שרת לנהל, משלמים לפי הרצה.' },
    { term: 'CloudWatch', aka: ['Amazon CloudWatch'], en: 'The AWS monitoring service: metrics (numbers over time), logs and alarms.', he: 'שירות הניטור של AWS: metrics (מספרים לאורך זמן), לוגים ו-alarms.' },
    { term: 'CloudTrail', aka: ['AWS CloudTrail'], en: 'The audit log of AWS API calls: who did what, when, from where.', he: 'יומן הביקורת של קריאות API ב-AWS: מי עשה מה, מתי ומאיפה.' },
    { term: 'VPC', aka: ['Virtual Private Cloud'], en: 'Virtual Private Cloud. Your own private network inside AWS.', he: 'Virtual Private Cloud. רשת פרטית משלך בתוך AWS.' },
    { term: 'PrivateLink', aka: ['VPC endpoint', 'interface endpoint', 'AWS PrivateLink'], en: 'A private network path from your VPC to an AWS service, so traffic does not use the public internet.', he: 'נתיב רשת פרטי מה-VPC שלך לשירות של AWS, כך שהתעבורה לא עוברת באינטרנט הציבורי.' },
    { term: 'KMS', aka: ['Key Management Service', 'customer managed key'], en: 'Key Management Service. It holds the encryption keys that protect your stored data.', he: 'Key Management Service. מחזיק את מפתחות ההצפנה שמגנים על המידע השמור שלך.' },
    { term: 'Quota', aka: ['quotas', 'Service Quotas'], en: 'A limit AWS puts on your account, per Region, for example tokens per minute for one model.', he: 'מגבלה ש-AWS שמה על החשבון שלך, לכל Region, למשל טוקנים לדקה למודל אחד.' },
    { term: 'Throttling', aka: ['ThrottlingException', 'throttled'], en: 'AWS rejecting requests (HTTP 429) because you went over a quota.', he: 'AWS דוחה בקשות (HTTP 429) כי עברת quota.' },
    { term: 'Model invocation logging', aka: ['invocation logging', 'invocation logs'], en: 'An optional Bedrock setting that saves full requests and responses to CloudWatch Logs or S3. Off by default.', he: 'הגדרה אופציונלית ב-Bedrock ששומרת בקשות ותשובות מלאות ל-CloudWatch Logs או ל-S3. כבויה כברירת מחדל.' },
    { term: 'Service role', aka: ['execution role'], en: 'A role that an AWS service (Lambda, Bedrock, an agent runtime) assumes to act for you.', he: 'role ששירות של AWS (Lambda, Bedrock, סביבת ריצה של סוכן) לוקח כדי לפעול בשמך.' }
  ],
  lessons: [
    {
      id: 'm02l1', minutes: 12,
      title: { en: 'Accounts, Regions and the three doors into AWS', he: 'חשבונות, Regions ושלוש הדלתות ל-AWS' },
      blocks: [
        { t: 'p', en: '[[AWS]] is a very large set of services that you rent and control through an API. It has more than 200 services. A GenAI developer needs about ten ideas from all of that. This module gives you exactly those, and nothing else.', he: '[[AWS]] היא אוסף גדול מאוד של שירותים ששוכרים ושולטים בהם דרך API. יש בה יותר מ-200 שירותים. מפתח GenAI צריך בערך עשרה רעיונות מתוך כל זה. המודול הזה נותן לך בדיוק אותם, ולא יותר.' },
        { t: 'h', en: 'The account: your box', he: 'החשבון: הקופסה שלך' },
        { t: 'p', en: 'An [[Account]] is a box. Everything you create is inside it, the bill is for it, and it has a 12-digit ID like `123456789012`. A company almost never has one account. It has many: one for development, one for staging, one for [[Production]], often one per team. Why? Because the walls between accounts are the strongest walls AWS has. A mistake in the dev account cannot delete production data, and each account has its own bill and its own limits.', he: '[[Account]] הוא קופסה. כל מה שאתה יוצר נמצא בתוכה, החשבונית היא שלה, ויש לה מזהה של 12 ספרות כמו `123456789012`. לחברה כמעט אף פעם אין חשבון אחד. יש לה הרבה: אחד לפיתוח, אחד ל-staging, אחד ל-[[Production]], ולפעמים אחד לכל צוות. למה? כי הקירות בין חשבונות הם הקירות הכי חזקים שיש ב-AWS. טעות בחשבון ה-dev לא יכולה למחוק מידע של production, ולכל חשבון יש חשבונית משלו ומגבלות משלו.' },
        { t: 'note', kind: 'jargon', en: 'When colleagues say "the org" they mean **AWS Organizations**: the tree of all the company accounts. One team (often called "platform" or "cloud team") owns it and can set rules for every account. You will meet those rules in the next lesson as [[SCP]]s.', he: 'כשעמיתים אומרים "the org" הם מתכוונים ל-**AWS Organizations**: העץ של כל חשבונות החברה. צוות אחד (בדרך כלל "platform" או "cloud team") הוא הבעלים ויכול לקבוע כללים לכל חשבון. תפגוש את הכללים האלה בשיעור הבא בשם [[SCP]].' },
        { t: 'h', en: 'The Region: where things live', he: 'ה-Region: איפה הדברים חיים' },
        { t: 'p', en: 'A [[Region]] is a place on the map with its own AWS data centers. Each has a code: `us-east-1` (N. Virginia), `us-west-2` (Oregon), `eu-central-1` (Frankfurt). Almost every resource lives in **one** Region. A guardrail that you create in `us-west-2` does not exist in `us-east-1`.', he: '[[Region]] הוא מקום על המפה עם מרכזי נתונים משלו של AWS. לכל אחד יש קוד: `us-east-1` (צפון וירג׳יניה), `us-west-2` (אורגון), `eu-central-1` (פרנקפורט). כמעט כל משאב חי ב-Region **אחד**. guardrail שיצרת ב-`us-west-2` לא קיים ב-`us-east-1`.' },
        { t: 'table', head: { en: ['The Region decides…', 'What it means for you'], he: ['ה-Region קובע…', 'מה זה אומר בשבילך'] }, rows: {
          en: [['**Which models you can call**', 'Not every model is in every Region. The docs page of each model (its "model card") lists the Regions.'], ['**Your limits**', 'A [[Quota]] is per account **and** per Region. A raised limit in one Region does not move to another.'], ['**Where data is processed**', 'Legal teams care about this ("data residency"). EU customer data often must stay in the EU.'], ['**Latency and price**', 'A Region close to your users answers a little faster. Prices can differ between Regions.']],
          he: [['**לאילו מודלים אפשר לקרוא**', 'לא כל מודל נמצא בכל Region. דף התיעוד של כל מודל (ה-"model card" שלו) מפרט את ה-Regions.'], ['**את המגבלות שלך**', '[[Quota]] היא לכל חשבון **וגם** לכל Region. מגבלה שהועלתה ב-Region אחד לא עוברת לאחר.'], ['**איפה המידע מעובד**', 'צוותים משפטיים מתעניינים בזה ("data residency"). מידע של לקוחות אירופאים לרוב חייב להישאר באירופה.'], ['**latency ומחיר**', 'Region קרוב למשתמשים עונה קצת יותר מהר. המחירים יכולים להיות שונים בין Regions.']] } },
        { t: 'note', kind: 'warn', en: 'The most common beginner bug on AWS: the console shows one Region (look at the top right corner) and your code calls another. The result is "resource not found" or an empty list, and nothing is actually broken. When something "disappeared", check the Region first.', he: 'הבאג הכי נפוץ של מתחילים ב-AWS: הקונסול מציג Region אחד (תסתכל בפינה הימנית העליונה) והקוד שלך קורא ל-Region אחר. התוצאה היא "resource not found" או רשימה ריקה, ושום דבר לא באמת שבור. כשמשהו "נעלם", קודם בודקים את ה-Region.' },
        { t: 'quiz', q: { en: 'You created a guardrail in the console and tested it there. Your Python code gets "resource not found" for the same guardrail ID. The ID is copied correctly. What do you check first?', he: 'יצרת guardrail בקונסול ובדקת אותו שם. קוד ה-Python שלך מקבל "resource not found" על אותו guardrail ID. המזהה הועתק נכון. מה בודקים קודם?' },
          options: { en: ['Whether the model supports guardrails', 'Whether your bill was paid', 'Whether the code uses the same Region as the console', 'Whether the guardrail needs 24 hours to become active'], he: ['האם המודל תומך ב-guardrails', 'האם החשבונית שולמה', 'האם הקוד משתמש באותו Region כמו הקונסול', 'האם ה-guardrail צריך 24 שעות כדי להפוך לפעיל'] },
          answer: 2, explain: { en: 'Resources are regional. If the console was on `us-west-2` and the client was created with `region_name="us-east-1"`, the guardrail really does not exist where the code is looking. There is no 24-hour wait for new resources.', he: 'משאבים הם אזוריים. אם הקונסול היה על `us-west-2` וה-client נוצר עם `region_name="us-east-1"`, ה-guardrail באמת לא קיים במקום שבו הקוד מחפש. אין המתנה של 24 שעות למשאבים חדשים.' } },
        { t: 'h', en: 'Three doors: console, CLI, SDK', he: 'שלוש דלתות: console, CLI, SDK' },
        { t: 'table', head: { en: ['Door', 'What it is', 'When you use it'], he: ['דלת', 'מה זה', 'מתי משתמשים'] }, rows: {
          en: [['[[Console]]', 'The website. Click and look.', 'Learning, exploring, checking what exists, reading logs.'], ['[[CLI]]', 'The `aws` command in a terminal.', 'Quick checks, scripts, "who am I logged in as?".'], ['[[SDK]]', 'A library in your code. In Python it is **boto3**.', 'Your application. This is where a GenAI developer lives.']],
          he: [['[[Console]]', 'האתר. לוחצים ומסתכלים.', 'למידה, חקירה, לבדוק מה קיים, לקרוא לוגים.'], ['[[CLI]]', 'הפקודה `aws` בטרמינל.', 'בדיקות מהירות, סקריפטים, "בתור מי אני מחובר?".'], ['[[SDK]]', 'ספרייה בתוך הקוד שלך. ב-Python זו **boto3**.', 'האפליקציה שלך. כאן חי מפתח GenAI.']] } },
        { t: 'p', en: 'All three doors lead to the same room: the AWS API. The console is only a website that calls the API for you. So everything you can click, you can also script. Pros click to learn and then write code, because code can be reviewed, repeated and put in version control.', he: 'כל שלוש הדלתות מובילות לאותו חדר: ה-API של AWS. הקונסול הוא רק אתר שקורא ל-API בשבילך. לכן כל מה שאפשר ללחוץ עליו, אפשר גם לכתוב בסקריפט. מקצוענים לוחצים כדי ללמוד ואז כותבים קוד, כי קוד אפשר לבדוק, לחזור עליו ולשמור ב-version control.' },
        { t: 'code', lang: 'python', code: 'import boto3\n\n# One client per service and per Region\nbedrock = boto3.client("bedrock", region_name="us-east-1")\n\nresp = bedrock.list_foundation_models()\nfor m in resp["modelSummaries"][:3]:\n    print(m["modelId"])', caption: { en: 'boto3: create a client for a service in a Region, then call methods on it. The CLI twin of this call is `aws bedrock list-foundation-models --region us-east-1`.', he: 'boto3: יוצרים client לשירות ב-Region, ואז קוראים למתודות שלו. המקבילה ב-CLI היא `aws bedrock list-foundation-models --region us-east-1`.' } },
        { t: 'fill', prompt: { en: 'Create a boto3 client for the service that runs model inference (`bedrock-runtime`), in the Oregon Region.', he: 'צור client של boto3 לשירות שמריץ inference של מודלים (`bedrock-runtime`), ב-Region של אורגון.' },
          lang: 'python', code: 'import {{1}}\n\nclient = boto3.{{2}}("bedrock-runtime", region_name="{{3}}")', blanks: [ { accept: ['boto3'], hint: { en: 'the Python SDK', he: 'ה-SDK של Python' } }, { accept: ['client'], hint: { en: 'the function that creates a service client', he: 'הפונקציה שיוצרת client לשירות' } }, { accept: ['us-west-2'], hint: { en: 'Oregon', he: 'אורגון' } } ],
          explain: { en: 'Always pass `region_name` in code that others will run. If you leave it out, boto3 takes the Region from the environment or the profile, and the same code behaves differently on another machine.', he: 'תמיד מעבירים `region_name` בקוד שאחרים יריצו. אם משמיטים אותו, boto3 לוקח את ה-Region מהסביבה או מה-profile, ואותו קוד מתנהג אחרת במכונה אחרת.' } },
        { t: 'h', en: 'ARN: the full name of a thing', he: 'ARN: השם המלא של דבר' },
        { t: 'p', en: 'Every resource has an [[ARN]] (Amazon Resource Name). You will paste ARNs into code, into policies and into the console all day. The parts are always in the same order, separated by colons:', he: 'לכל משאב יש [[ARN]] (Amazon Resource Name). תדביק ARNs בקוד, ב-policies ובקונסול כל היום. החלקים תמיד באותו סדר, מופרדים בנקודתיים:' },
        { t: 'code', lang: 'text', code: 'arn : aws : service : region    : account-id   : resource\n\narn:aws:bedrock:us-east-1:123456789012:guardrail/abc123def456\narn:aws:bedrock:us-east-1::foundation-model/amazon.nova-2-lite-v1:0\narn:aws:iam::123456789012:role/support-bot-role\narn:aws:s3:::acme-support-docs', caption: { en: 'Four real shapes. Look at which parts are empty: a foundation model has no account (it belongs to AWS, not to you), an IAM role has no Region (IAM is global), an S3 bucket has neither (bucket names are unique in the world).', he: 'ארבע צורות אמיתיות. שים לב אילו חלקים ריקים: ל-foundation model אין חשבון (הוא שייך ל-AWS, לא לך), ל-IAM role אין Region (IAM הוא גלובלי), ול-S3 bucket אין אף אחד מהם (שמות buckets ייחודיים בכל העולם).' } },
        { t: 'quiz', q: { en: 'Look at `arn:aws:bedrock:us-east-1::foundation-model/amazon.nova-2-lite-v1:0`. Why is the account field empty?', he: 'הסתכל על `arn:aws:bedrock:us-east-1::foundation-model/amazon.nova-2-lite-v1:0`. למה שדה החשבון ריק?' },
          options: { en: ['The base model belongs to AWS, not to your account', 'It is a typo, every ARN needs an account ID', 'The model is free', 'The model is available in every Region'], he: ['מודל הבסיס שייך ל-AWS, לא לחשבון שלך', 'זו טעות הקלדה, כל ARN צריך מזהה חשבון', 'המודל חינמי', 'המודל זמין בכל Region'] },
          answer: 0, explain: { en: 'Foundation models are shared resources that AWS hosts, so there is no owner account in the ARN. Things that **you** create (a guardrail, a knowledge base, an inference profile of your own) carry your account ID. The Region part is still there: the model ARN is per Region.', he: 'foundation models הם משאבים משותפים ש-AWS מארחת, ולכן אין חשבון בעלים ב-ARN. דברים ש**אתה** יוצר (guardrail, knowledge base, inference profile משלך) נושאים את מזהה החשבון שלך. חלק ה-Region עדיין שם: ה-ARN של המודל הוא לכל Region.' } },
        { t: 'match', prompt: { en: 'Match each ARN to what it names.', he: 'התאם כל ARN למה שהוא מציין.' }, pairs: [
          { a: '`arn:aws:iam::123456789012:role/app-role`', b: { en: 'An identity that code can assume', he: 'זהות שקוד יכול לקחת (assume)' } },
          { a: '`arn:aws:s3:::acme-docs`', b: { en: 'A place where files are stored', he: 'מקום שבו קבצים מאוחסנים' } },
          { a: '`arn:aws:bedrock:us-east-1::foundation-model/…`', b: { en: 'A base model hosted by AWS in one Region', he: 'מודל בסיס ש-AWS מארחת ב-Region אחד' } },
          { a: '`arn:aws:bedrock:us-east-1:123456789012:guardrail/…`', b: { en: 'A Bedrock resource created in your account', he: 'משאב של Bedrock שנוצר בחשבון שלך' } }
        ] },
        { t: 'h', en: 'How AWS bills you', he: 'איך AWS מחייבת אותך' },
        { t: 'p', en: 'AWS is **pay per use**. There is no monthly fee for having an account. Each service has its own meter. For a GenAI developer the meters that matter are:', he: 'ב-AWS **משלמים לפי שימוש**. אין תשלום חודשי על עצם קיום החשבון. לכל שירות יש מונה משלו. למפתח GenAI המונים החשובים הם:' },
        { t: 'list', en: ['**Tokens**: model calls on [[Amazon Bedrock]] are billed per input token and per output token (module 3 goes deep on this).', '**Time**: capacity that you reserve is billed per hour, whether you use it or not.', '**Storage**: files in [[S3]] and logs in [[CloudWatch]] are billed per GB per month.', '**Requests and run time**: a [[Lambda]] function is billed per call and per millisecond it runs.'], he: ['**טוקנים**: קריאות למודלים ב-[[Amazon Bedrock]] מחויבות לפי טוקן קלט ולפי טוקן פלט (מודול 3 נכנס לזה לעומק).', '**זמן**: קיבולת שמזמינים מראש מחויבת לפי שעה, בין אם משתמשים בה ובין אם לא.', '**אחסון**: קבצים ב-[[S3]] ולוגים ב-[[CloudWatch]] מחויבים לפי GB לחודש.', '**בקשות וזמן ריצה**: פונקציית [[Lambda]] מחויבת לפי קריאה ולפי אלפיות השנייה שהיא רצה.'] },
        { t: 'note', kind: 'tip', en: 'On day one in a new account, create a budget alert in **AWS Budgets** (the billing tool that emails you when cost passes a number you choose). And put **tags** (key-value labels such as `team=support`) on what you create. After you activate a tag under **Cost allocation tags** in the Billing and Cost Management console, the bill can be split by it. Activation can take up to 24 hours and does not go back in time, so do it early.', he: 'ביום הראשון בחשבון חדש, צור התראת תקציב ב-**AWS Budgets** (כלי החיוב ששולח מייל כשהעלות עוברת מספר שבחרת). ושים **tags** (תוויות key-value כמו `team=support`) על מה שאתה יוצר. אחרי שמפעילים tag תחת **Cost allocation tags** בקונסול של Billing and Cost Management, אפשר לפצל את החשבונית לפיו. ההפעלה יכולה לקחת עד 24 שעות ולא חלה אחורה בזמן, אז עושים את זה מוקדם.' },
        { t: 'quiz', q: { en: 'Your team goes home for a long weekend. Nobody uses the system. Which of these keeps costing money the whole time?', he: 'הצוות שלך הולך הביתה לסוף שבוע ארוך. אף אחד לא משתמש במערכת. מה מהבאים ממשיך לעלות כסף כל הזמן?' },
          options: { en: ['A Bedrock model that you call on demand', 'An IAM role', 'A Lambda function that nobody calls', 'Model capacity that you reserved by the hour'], he: ['מודל ב-Bedrock שקוראים לו on demand', 'IAM role', 'פונקציית Lambda שאף אחד לא קורא לה', 'קיבולת מודל שהוזמנה לפי שעה'] },
          answer: 3, explain: { en: 'On-demand model calls and Lambda cost nothing when there are no calls. IAM is free. Reserved capacity (in Bedrock: Provisioned Throughput) is billed every hour until you delete it. "I forgot to delete it" is the classic surprise bill.', he: 'קריאות on-demand למודל ו-Lambda לא עולות כלום כשאין קריאות. IAM חינמי. קיבולת שמורה (ב-Bedrock: Provisioned Throughput) מחויבת כל שעה עד שמוחקים אותה. "שכחתי למחוק" היא החשבונית המפתיעה הקלאסית.' } },
        { t: 'h', en: 'Shared responsibility', he: 'אחריות משותפת' },
        { t: 'p', en: 'The [[Shared responsibility model]] is one sentence: **AWS is responsible for the security *of* the cloud, you are responsible for security *in* the cloud.** AWS guards the buildings, the hardware, the network and the service itself. You decide who has access, what data you send, how your application is configured and how it behaves.', he: 'ה-[[Shared responsibility model]] הוא משפט אחד: **AWS אחראית לאבטחה *של* הענן, אתה אחראי לאבטחה *בתוך* הענן.** AWS שומרת על הבניינים, החומרה, הרשת והשירות עצמו. אתה מחליט למי יש גישה, איזה מידע שולחים, איך האפליקציה מוגדרת ואיך היא מתנהגת.' },
        { t: 'p', en: 'For GenAI there is a sharp example. The Bedrock docs say that prompt injection (a user or a document that tricks the model into ignoring your instructions) is an application-level problem, "similar to SQL injection", and that preventing it is the customer\'s job. AWS gives you tools such as guardrails. Using them is on you.', he: 'ב-GenAI יש דוגמה חדה. התיעוד של Bedrock אומר ש-prompt injection (משתמש או מסמך שמרמים את המודל להתעלם מההוראות שלך) היא בעיה ברמת האפליקציה, "בדומה ל-SQL injection", ושמניעתה היא העבודה של הלקוח. AWS נותנת לך כלים כמו guardrails. להשתמש בהם זה עליך.' },
        { t: 'quiz', q: { en: 'Which of these are **your** responsibility when you build on Bedrock? Pick all that apply.', he: 'מה מהבאים באחריות **שלך** כשאתה בונה על Bedrock? בחר את כל הנכונים.' },
          options: { en: ['Deciding which roles may invoke which models', 'Patching the servers that run the model', 'Checking user input and documents for prompt injection', 'Physical security of the data center'], he: ['להחליט אילו roles רשאים להפעיל אילו מודלים', 'לעדכן את השרתים שמריצים את המודל', 'לבדוק קלט של משתמשים ומסמכים מפני prompt injection', 'אבטחה פיזית של מרכז הנתונים'] },
          answer: [0, 2], explain: { en: 'Bedrock is a [[Managed service]]: AWS runs and patches the servers and guards the buildings. Access control (IAM) and the behavior of your application are yours.', he: 'Bedrock הוא [[Managed service]]: AWS מריצה ומעדכנת את השרתים ושומרת על הבניינים. בקרת גישה (IAM) וההתנהגות של האפליקציה שלך הן שלך.' } },
        { t: 'reveal', q: { en: 'A customer says: "Bedrock is a managed service, so security is Amazon\'s problem, right?" Answer in your own words.', he: 'לקוח אומר: "Bedrock הוא managed service, אז אבטחה זו בעיה של Amazon, נכון?" ענה במילים שלך.' },
          a: { en: 'Only half. AWS secures the service: the hardware, the network, the servers that run the models. We are still responsible for everything we configure and build: who is allowed to call the models (IAM), which data we put into prompts, where logs with prompts are stored and who can read them, encryption choices, and how the application handles bad input such as prompt injection. If we give every developer full access or log customer data into an open bucket, that is our failure, not Amazon\'s.', he: 'רק חצי. AWS מאבטחת את השירות: החומרה, הרשת, השרתים שמריצים את המודלים. אנחנו עדיין אחראים לכל מה שאנחנו מגדירים ובונים: מי רשאי לקרוא למודלים (IAM), איזה מידע אנחנו מכניסים לפרומפטים, איפה נשמרים לוגים עם פרומפטים ומי יכול לקרוא אותם, בחירות הצפנה, ואיך האפליקציה מטפלת בקלט בעייתי כמו prompt injection. אם ניתן לכל מפתח גישה מלאה או נכתוב מידע של לקוחות ל-bucket פתוח, זה כישלון שלנו, לא של Amazon.' } }
      ]
    },
    {
      id: 'm02l2', minutes: 14,
      title: { en: 'IAM without fear', he: 'IAM בלי פחד' },
      blocks: [
        { t: 'p', en: '[[IAM]] answers one question, on **every** API call: "Is this caller allowed to do this action on this resource?" Every call is checked, also calls that come from inside AWS. Most of the times that "it does not work" on AWS, the real answer is that IAM said no. Learn to read IAM and you remove most of the pain.', he: '[[IAM]] עונה על שאלה אחת, ב**כל** קריאת API: "האם למי שקורא מותר לעשות את הפעולה הזו על המשאב הזה?" כל קריאה נבדקת, גם קריאות שמגיעות מתוך AWS. ברוב הפעמים ש"זה לא עובד" ב-AWS, התשובה האמיתית היא ש-IAM אמר לא. למד לקרוא IAM ותוריד את רוב הכאב.' },
        { t: 'h', en: 'Who is calling: the principal', he: 'מי קורא: ה-principal' },
        { t: 'p', en: 'The caller is called the [[Principal]]. There are two kinds you must know.', he: 'למי שקורא קוראים [[Principal]]. יש שני סוגים שחייבים להכיר.' },
        { t: 'table', head: { en: ['', 'IAM user', 'IAM role'], he: ['', 'IAM user', 'IAM role'] }, rows: {
          en: [['What it is', 'A permanent identity', 'A "hat" that someone puts on for a while'], ['Credentials', 'Long-term: a password and [[Access key]]s that never expire by themselves', '[[Temporary credentials]] that expire after minutes or hours'], ['Used by', 'One person or one old script', 'Applications (Lambda, containers, agents), people who log in through SSO, other accounts'], ['Today', 'Avoid where you can', 'The default choice']],
          he: [['מה זה', 'זהות קבועה', '"כובע" שמישהו חובש לזמן מה'], ['Credentials', 'ארוכי-טווח: סיסמה ו-[[Access key]]s שלא פג תוקפם מעצמם', '[[Temporary credentials]] שפג תוקפם אחרי דקות או שעות'], ['מי משתמש', 'אדם אחד או סקריפט ישן אחד', 'אפליקציות (Lambda, קונטיינרים, סוכנים), אנשים שמתחברים דרך SSO, חשבונות אחרים'], ['היום', 'נמנעים כשאפשר', 'ברירת המחדל']] } },
        { t: 'p', en: 'An [[IAM role]] has **two** policies, and beginners mix them up. The [[Trust policy]] says **who may put the hat on**. The permissions policy says **what the hat lets you do**. Putting the hat on is called "assuming the role". Behind the scenes a service named [[STS]] hands out the temporary credentials.', he: 'ל-[[IAM role]] יש **שתי** policies, ומתחילים מתבלבלים ביניהן. ה-[[Trust policy]] אומרת **מי רשאי לחבוש את הכובע**. ה-permissions policy אומרת **מה הכובע מרשה לעשות**. לחבישת הכובע קוראים "assume role". מאחורי הקלעים שירות בשם [[STS]] מחלק את ה-credentials הזמניים.' },
        { t: 'code', lang: 'json', code: '{\n  "Version": "2012-10-17",\n  "Statement": [\n    {\n      "Effect": "Allow",\n      "Principal": { "Service": "lambda.amazonaws.com" },\n      "Action": "sts:AssumeRole"\n    }\n  ]\n}', caption: { en: 'A trust policy. It says: the Lambda service may assume this role. A role that a service assumes for you is called a [[Service role]] or execution role.', he: 'trust policy. היא אומרת: שירות Lambda רשאי לקחת את ה-role הזה. role ששירות לוקח בשבילך נקרא [[Service role]] או execution role.' } },
        { t: 'h', en: 'The policy document', he: 'מסמך ה-policy' },
        { t: 'p', en: 'A [[Policy]] is a JSON document with a list of statements. Each statement has three main fields. Read them as one sentence: **Effect** (allow or deny) this **Action** (which API calls) on this **Resource** (which ARNs).', he: '[[Policy]] היא מסמך JSON עם רשימת statements. לכל statement יש שלושה שדות עיקריים. קוראים אותם כמשפט אחד: **Effect** (להרשות או לאסור) את ה-**Action** הזו (אילו קריאות API) על ה-**Resource** הזה (אילו ARNs).' },
        { t: 'code', lang: 'json', code: '{\n  "Version": "2012-10-17",\n  "Statement": [\n    {\n      "Effect": "Allow",\n      "Action": "bedrock:InvokeModel",\n      "Resource": "arn:aws:bedrock:us-east-1::foundation-model/amazon.nova-2-lite-v1:0"\n    }\n  ]\n}', caption: { en: 'Read it aloud: "Allow the action InvokeModel of the service bedrock, on the Nova 2 Lite model in us-east-1." Nothing else is allowed.', he: 'קרא בקול: "הרשה את הפעולה InvokeModel של השירות bedrock, על המודל Nova 2 Lite ב-us-east-1." שום דבר אחר לא מורשה.' } },
        { t: 'list', en: ['`Action` is always `service:ApiName`. Wildcards work: `bedrock:Get*`, `bedrock:*`.', '`Resource` is an ARN or a pattern. `"*"` means "every resource".', '`Condition` (optional) adds an "only if", for example only in certain Regions or only through a certain guardrail.', '`"Version": "2012-10-17"` is the version of the policy language. It is always this date. Just copy it.'], he: ['`Action` הוא תמיד `service:ApiName`. אפשר wildcards: `bedrock:Get*`, `bedrock:*`.', '`Resource` הוא ARN או תבנית. `"*"` פירושו "כל משאב".', '`Condition` (אופציונלי) מוסיף "רק אם", למשל רק ב-Regions מסוימים או רק דרך guardrail מסוים.', '`"Version": "2012-10-17"` היא גרסת שפת ה-policy. זה תמיד התאריך הזה. פשוט מעתיקים.'] },
        { t: 'h', en: 'How IAM decides', he: 'איך IAM מחליט' },
        { t: 'flow', steps: { en: ['Request arrives', 'Who is the principal?', 'Collect every policy that applies', 'Any explicit Deny? → denied', 'Any Allow? → allowed', 'Nothing matched → denied'], he: ['בקשה מגיעה', 'מי ה-principal?', 'אוספים כל policy שחלה', 'יש Deny מפורש? ← נדחה', 'יש Allow? ← מאושר', 'כלום לא התאים ← נדחה'] }, caption: { en: 'Three rules to remember: everything is denied by default, an Allow opens a door, and an [[Explicit deny]] always wins.', he: 'שלושה כללים לזכור: הכול אסור כברירת מחדל, Allow פותח דלת, ו-[[Explicit deny]] תמיד מנצח.' } },
        { t: 'quiz', q: { en: 'A role has only the policy shown above (Allow `bedrock:InvokeModel` on Nova 2 Lite in us-east-1). The code calls that same model, in us-east-1, but with **streaming**. What happens?', he: 'ל-role יש רק את ה-policy שלמעלה (Allow ל-`bedrock:InvokeModel` על Nova 2 Lite ב-us-east-1). הקוד קורא לאותו מודל, ב-us-east-1, אבל עם **streaming**. מה קורה?' },
          options: { en: ['It works, streaming is only a different output format', 'AccessDeniedException: streaming needs the action `bedrock:InvokeModelWithResponseStream`', 'ThrottlingException, because streaming uses more quota', 'It works, but the answer arrives in one piece'], he: ['עובד, streaming הוא רק פורמט פלט אחר', 'AccessDeniedException: ל-streaming צריך את הפעולה `bedrock:InvokeModelWithResponseStream`', 'ThrottlingException, כי streaming צורך יותר quota', 'עובד, אבל התשובה מגיעה בחתיכה אחת'] },
          answer: 1, explain: { en: 'Bedrock has two inference actions: `bedrock:InvokeModel` and `bedrock:InvokeModelWithResponseStream`. The streaming calls check the second one. It was never allowed, so the default deny applies. This is a very common real bug: the app works in tests and fails the day someone turns streaming on.', he: 'ל-Bedrock יש שתי פעולות inference: `bedrock:InvokeModel` ו-`bedrock:InvokeModelWithResponseStream`. קריאות ה-streaming בודקות את השנייה. היא מעולם לא הורשתה, אז חל ה-deny של ברירת המחדל. זה באג אמיתי נפוץ מאוד: האפליקציה עובדת בבדיקות ונכשלת ביום שמישהו מדליק streaming.' } },
        { t: 'code', lang: 'json', code: '{\n  "Version": "2012-10-17",\n  "Statement": [\n    { "Effect": "Allow", "Action": "bedrock:*", "Resource": "*" },\n    { "Effect": "Deny",\n      "Action": ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"],\n      "Resource": "arn:aws:bedrock:*::foundation-model/anthropic.*" }\n  ]\n}', caption: { en: 'Read this policy, then answer the question below.', he: 'קרא את ה-policy הזו, ואז ענה על השאלה שמתחת.' } },
        { t: 'quiz', q: { en: 'What can a role with the policy above do?', he: 'מה יכול לעשות role עם ה-policy שלמעלה?' },
          options: { en: ['Nothing in Bedrock, because a Deny cancels the whole policy', 'Everything in Bedrock, because the Allow comes first', 'Only invoke Anthropic models', 'Everything in Bedrock except invoking Anthropic base models'], he: ['כלום ב-Bedrock, כי Deny מבטל את כל ה-policy', 'הכול ב-Bedrock, כי ה-Allow מופיע קודם', 'רק להפעיל מודלים של Anthropic', 'הכול ב-Bedrock חוץ מהפעלת מודלי בסיס של Anthropic'] },
          answer: 3, explain: { en: 'The order of statements does not matter. A Deny blocks only what it matches (two actions, on ARNs that match the pattern), and there it beats the Allow. Everything else stays allowed. This Deny pattern is how a company blocks a model it does not want used. The Bedrock docs say to block with a Deny on `bedrock:InvokeModel` for the model ARN.', he: 'סדר ה-statements לא משנה. Deny חוסם רק את מה שהוא מתאים לו (שתי פעולות, על ARNs שמתאימים לתבנית), ושם הוא מנצח את ה-Allow. כל השאר נשאר מורשה. כך חברה חוסמת מודל שהיא לא רוצה שישתמשו בו. התיעוד של Bedrock אומר לחסום עם Deny על `bedrock:InvokeModel` ל-ARN של המודל.' } },
        { t: 'fill', prompt: { en: 'Write the policy for a support bot. It may call exactly one model, Nova 2 Lite in us-east-1, with and without streaming.', he: 'כתוב את ה-policy לבוט תמיכה. מותר לו לקרוא למודל אחד בדיוק, Nova 2 Lite ב-us-east-1, עם ובלי streaming.' },
          lang: 'json', code: '{\n  "Version": "2012-10-17",\n  "Statement": [\n    {\n      "Effect": "{{1}}",\n      "Action": [\n        "bedrock:{{2}}",\n        "bedrock:{{3}}"\n      ],\n      "Resource": "arn:aws:bedrock:us-east-1::{{4}}/amazon.nova-2-lite-v1:0"\n    }\n  ]\n}', blanks: [ { accept: ['Allow'], hint: { en: 'Allow or Deny', he: 'Allow או Deny' } }, { accept: ['InvokeModel'], hint: { en: 'the non-streaming inference action', he: 'פעולת ה-inference בלי streaming' } }, { accept: ['InvokeModelWithResponseStream'], hint: { en: 'the streaming inference action', he: 'פעולת ה-inference עם streaming' } }, { accept: ['foundation-model'], hint: { en: 'the resource type of a base model', he: 'סוג המשאב של מודל בסיס' } } ],
          explain: { en: 'These are the two real IAM actions for model inference on the main Bedrock endpoint. The Converse API that you will use in module 3 is authorized by the same two actions. This is [[Least privilege]]: one model, one Region, two actions.', he: 'אלה שתי פעולות ה-IAM האמיתיות ל-inference של מודלים ב-endpoint הראשי של Bedrock. ה-Converse API שתשתמש בו במודול 3 מאושר על ידי אותן שתי פעולות. זה [[Least privilege]]: מודל אחד, Region אחד, שתי פעולות.' } },
        { t: 'h', en: 'Least privilege, and the shortcuts people take', he: 'Least privilege, והקיצורים שאנשים לוקחים' },
        { t: 'p', en: '[[Least privilege]] means: give only what the job needs. The shortcut is a [[Managed policy]], a ready-made policy from AWS. Know these three for Bedrock:', he: '[[Least privilege]] אומר: נותנים רק מה שהעבודה צריכה. הקיצור הוא [[Managed policy]], policy מוכנה מ-AWS. הכר את שלוש אלה ל-Bedrock:' },
        { t: 'table', head: { en: ['Managed policy', 'What it gives', 'Good for'], he: ['Managed policy', 'מה היא נותנת', 'טוב בשביל'] }, rows: {
          en: [['`AmazonBedrockFullAccess`', '`bedrock:*` and some helper permissions', 'Your own sandbox account. Not a production application.'], ['`AmazonBedrockLimitedAccess`', 'Invoke models, basic create and delete of core resources, use API keys', 'A developer who builds with models'], ['`AmazonBedrockReadOnly`', 'Look at all Bedrock resources, change nothing', 'Auditors, dashboards']],
          he: [['`AmazonBedrockFullAccess`', '`bedrock:*` ועוד כמה הרשאות עזר', 'חשבון sandbox משלך. לא אפליקציית production.'], ['`AmazonBedrockLimitedAccess`', 'הפעלת מודלים, יצירה ומחיקה בסיסיות של משאבי ליבה, שימוש ב-API keys', 'מפתח שבונה עם מודלים'], ['`AmazonBedrockReadOnly`', 'לראות את כל משאבי Bedrock, לא לשנות כלום', 'מבקרים, דשבורדים']] } },
        { t: 'note', kind: 'tip', en: 'A pattern that works: start wide in your **sandbox** so you can learn fast. Before production, write a narrow policy with exactly the actions and ARNs the application uses. An application role with `bedrock:*` on `*` can delete your guardrails and buy reserved capacity. An agent that got tricked by a prompt injection acts with the permissions of its role, so a narrow role is also your last line of defense.', he: 'דפוס שעובד: מתחילים רחב ב-**sandbox** כדי ללמוד מהר. לפני production כותבים policy צרה עם בדיוק הפעולות וה-ARNs שהאפליקציה משתמשת בהם. role של אפליקציה עם `bedrock:*` על `*` יכול למחוק את ה-guardrails שלך ולקנות קיבולת שמורה. סוכן שרומה על ידי prompt injection פועל עם ההרשאות של ה-role שלו, כך ש-role צר הוא גם קו ההגנה האחרון שלך.' },
        { t: 'h', en: 'Reading an AccessDeniedException', he: 'איך קוראים AccessDeniedException' },
        { t: 'p', en: 'When IAM says no, you get an [[AccessDeniedException]]. Do not panic and do not add `*` everywhere. The message tells you almost everything:', he: 'כש-IAM אומר לא, מקבלים [[AccessDeniedException]]. לא נלחצים ולא מוסיפים `*` בכל מקום. ההודעה מספרת כמעט הכול:' },
        { t: 'code', lang: 'text', code: 'An error occurred (AccessDeniedException) when calling the Converse operation:\nUser: arn:aws:sts::123456789012:assumed-role/support-bot-role/session-1\nis not authorized to perform: bedrock:InvokeModel\non resource: arn:aws:bedrock:us-west-2::foundation-model/amazon.nova-2-lite-v1:0\nbecause no identity-based policy allows the bedrock:InvokeModel action', caption: { en: 'An illustration of the usual shape of the message. It has four facts: **who** (the role `support-bot-role`), **which action**, **which resource** (note the Region: us-west-2, while our policy allowed us-east-1), and **why**.', he: 'המחשה של הצורה הרגילה של ההודעה. יש בה ארבע עובדות: **מי** (ה-role בשם `support-bot-role`), **איזו פעולה**, **איזה משאב** (שים לב ל-Region: us-west-2, בזמן שה-policy שלנו הרשתה us-east-1), ו**למה**.' } },
        { t: 'p', en: 'The "why" has a few standard endings. "No identity-based policy allows" means nobody gave the permission. "With an explicit deny" means somebody forbade it on purpose, often in an [[SCP]]: a rule that the organization puts on the whole account. An SCP never gives permissions. It only sets the outer limit, and even an administrator of the account cannot pass it.', he: 'ל"למה" יש כמה סיומות קבועות. "No identity-based policy allows" אומר שאף אחד לא נתן את ההרשאה. "With an explicit deny" אומר שמישהו אסר את זה בכוונה, לעיתים קרובות ב-[[SCP]]: כלל שהארגון שם על כל החשבון. SCP אף פעם לא נותן הרשאות. הוא רק קובע את הגבול החיצוני, ואפילו מנהל של החשבון לא יכול לעבור אותו.' },
        { t: 'note', kind: 'info', en: 'Bedrock has a few special reasons for AccessDenied that are not about your policy text. You will meet them in module 3, but remember the list:\n1. Converse is authorized by `bedrock:InvokeModel`. A policy that lists some other action name for it gives nothing.\n2. When you call a model through a cross-Region inference profile, the policy must allow the profile ARN **and** the model ARN in every Region the profile can route to.\n3. The first call to a model from some providers starts an AWS Marketplace subscription. The caller then also needs `aws-marketplace:Subscribe`, `aws-marketplace:Unsubscribe` and `aws-marketplace:ViewSubscriptions`, and the account needs a valid payment method.', he: 'ל-Bedrock יש כמה סיבות מיוחדות ל-AccessDenied שלא קשורות לטקסט ה-policy שלך. תפגוש אותן במודול 3, אבל זכור את הרשימה:\n1. Converse מאושר על ידי `bedrock:InvokeModel`. policy שרושמת בשבילו שם פעולה אחר לא נותנת כלום.\n2. כשקוראים למודל דרך cross-Region inference profile, ה-policy חייבת להרשות את ה-ARN של ה-profile **וגם** את ה-ARN של המודל בכל Region שה-profile יכול לנתב אליו.\n3. הקריאה הראשונה למודל של חלק מהספקים מתחילה מנוי ב-AWS Marketplace. מי שקורא צריך אז גם `aws-marketplace:Subscribe`, `aws-marketplace:Unsubscribe` ו-`aws-marketplace:ViewSubscriptions`, ולחשבון צריך להיות אמצעי תשלום תקף.' },
        { t: 'quiz', q: { en: 'Your code calls Bedrock and works on your laptop. You deploy the same code to a Lambda function, in the same account and Region, and it fails with AccessDeniedException. What is the most likely reason?', he: 'הקוד שלך קורא ל-Bedrock ועובד על הלפטופ. אתה מעלה את אותו קוד לפונקציית Lambda, באותו חשבון ו-Region, והוא נכשל עם AccessDeniedException. מה הסיבה הכי סבירה?' },
          options: { en: ['On Lambda the principal is the function\'s execution role, and that role has no Bedrock permission', 'Lambda cannot call Bedrock', 'The model is not available to Lambda functions', 'boto3 in Lambda is too old to sign requests'], he: ['ב-Lambda ה-principal הוא ה-execution role של הפונקציה, ול-role הזה אין הרשאה ל-Bedrock', 'Lambda לא יכולה לקרוא ל-Bedrock', 'המודל לא זמין לפונקציות Lambda', 'boto3 ב-Lambda ישן מדי כדי לחתום על בקשות'] },
          answer: 0, explain: { en: 'Same code, different caller. On the laptop the principal is **you** (your SSO role, usually wide). In Lambda it is the function\'s execution role, which starts with almost no permissions. "Works on my machine" on AWS nearly always means "works with my permissions".', he: 'אותו קוד, קורא אחר. על הלפטופ ה-principal הוא **אתה** (ה-role שלך מ-SSO, בדרך כלל רחב). ב-Lambda זה ה-execution role של הפונקציה, שמתחיל כמעט בלי הרשאות. "עובד אצלי" ב-AWS כמעט תמיד אומר "עובד עם ההרשאות שלי".' } },
        { t: 'order', prompt: { en: 'You get an AccessDeniedException. Put the debugging steps in the order a pro does them.', he: 'קיבלת AccessDeniedException. סדר את שלבי הדיבוג בסדר שבו מקצוען עושה אותם.' }, items: { en: ['Read the full error message: who, action, resource, reason', 'Confirm who the caller really is (`aws sts get-caller-identity` or the role of the compute)', 'Compare the action and the resource ARN (Region, account, name) with the policy on that role', 'If the reason says "explicit deny", look for an SCP or another Deny and talk to the team that owns it', 'Add the smallest permission that fixes it, and test again'], he: ['לקרוא את הודעת השגיאה המלאה: מי, פעולה, משאב, סיבה', 'לוודא מי באמת הקורא (`aws sts get-caller-identity` או ה-role של סביבת הריצה)', 'להשוות את הפעולה ואת ה-ARN של המשאב (Region, חשבון, שם) ל-policy שעל ה-role הזה', 'אם הסיבה אומרת "explicit deny", לחפש SCP או Deny אחר ולדבר עם הצוות שאחראי עליו', 'להוסיף את ההרשאה הקטנה ביותר שפותרת, ולבדוק שוב'] },
          explain: { en: 'Most wasted hours come from skipping step 2: people fix the policy of the wrong identity. And the last step matters too: the fix is the missing action on the needed ARN, not `"Action": "*"`.', he: 'רוב השעות המבוזבזות באות מדילוג על שלב 2: אנשים מתקנים את ה-policy של הזהות הלא נכונה. וגם השלב האחרון חשוב: התיקון הוא הפעולה החסרה על ה-ARN הנדרש, לא `"Action": "*"`.' } },
        { t: 'quiz', q: { en: 'You are an administrator in your team\'s account, with full access. A call to a Bedrock model in an EU Region still fails: "…with an explicit deny in a service control policy". What does it mean?', he: 'אתה מנהל בחשבון של הצוות, עם גישה מלאה. קריאה למודל של Bedrock ב-Region באירופה עדיין נכשלת: "…with an explicit deny in a service control policy". מה זה אומר?' },
          options: { en: ['Your administrator policy has a typo', 'The model does not exist in that Region', 'The organization set a rule above your account that blocks this, and only the team that owns the organization can change it', 'You must wait until your permissions spread to the EU'], he: ['יש טעות הקלדה ב-policy של המנהל', 'המודל לא קיים ב-Region הזה', 'הארגון קבע כלל מעל החשבון שלך שחוסם את זה, ורק הצוות שאחראי על הארגון יכול לשנות אותו', 'צריך לחכות עד שההרשאות יתפשטו לאירופה'] },
          answer: 2, explain: { en: 'An [[SCP]] is a limit from the organization. Many companies use one to allow only certain Regions. No policy inside the account can override it, so the fix is a conversation with the platform team, not more JSON. This matters a lot in Bedrock because cross-Region inference sends requests to other Regions (module 3).', he: '[[SCP]] הוא מגבלה מהארגון. הרבה חברות משתמשות באחד כדי להרשות רק Regions מסוימים. שום policy בתוך החשבון לא יכולה לעקוף אותו, אז התיקון הוא שיחה עם צוות ה-platform, לא עוד JSON. זה חשוב מאוד ב-Bedrock כי cross-Region inference שולח בקשות ל-Regions אחרים (מודול 3).' } },
        { t: 'reveal', q: { en: 'Interview question: "Why do we prefer IAM roles over IAM users with access keys?"', he: 'שאלת ראיון: "למה מעדיפים IAM roles על פני IAM users עם access keys?"' },
          a: { en: 'A user has long-term keys. They sit in files and laptops, they get copied into code and chat, and if one leaks it works until somebody notices and deletes it. A role has no stored secret. Whoever assumes it gets temporary credentials that expire by themselves, so a leak has a short life. Roles also fit how systems really work: a Lambda function or an agent gets its role automatically, with no key to store or rotate, and each workload can have its own narrow role. And with roles the audit log shows which role session did what.', he: 'למשתמש יש מפתחות ארוכי-טווח. הם יושבים בקבצים ובלפטופים, מועתקים לקוד ולצ׳אט, ואם אחד דולף הוא עובד עד שמישהו שם לב ומוחק אותו. ל-role אין סוד שמור. מי שלוקח אותו מקבל credentials זמניים שפג תוקפם מעצמם, כך שלדליפה יש חיים קצרים. roles גם מתאימים לאיך שמערכות באמת עובדות: פונקציית Lambda או סוכן מקבלים את ה-role שלהם אוטומטית, בלי מפתח לשמור או להחליף, ולכל workload יכול להיות role צר משלו. ועם roles יומן הביקורת מראה איזה session של איזה role עשה מה.' } }
      ]
    },
    {
      id: 'm02l3', minutes: 14,
      title: { en: 'Credentials for developers', he: 'Credentials למפתחים' },
      blocks: [
        { t: 'p', en: 'Every request to AWS must prove who sent it. The proof is a signature made with your credentials, in a format called [[SigV4]]. You never compute it by hand: the [[SDK]] and the [[CLI]] sign every request for you. Your only job is to make sure they can **find** credentials, and that they find the **right** ones.', he: 'כל בקשה ל-AWS חייבת להוכיח מי שלח אותה. ההוכחה היא חתימה שנוצרת עם ה-credentials שלך, בפורמט שנקרא [[SigV4]]. אף פעם לא מחשבים אותה ביד: ה-[[SDK]] וה-[[CLI]] חותמים על כל בקשה בשבילך. העבודה היחידה שלך היא לוודא שהם יכולים **למצוא** credentials, ושהם מוצאים את ה**נכונים**.' },
        { t: 'h', en: 'Three kinds of credentials', he: 'שלושה סוגי credentials' },
        { t: 'table', head: { en: ['Kind', 'Looks like', 'Lives for', 'Use it for'], he: ['סוג', 'איך נראה', 'כמה זמן חי', 'למה משתמשים'] }, rows: {
          en: [['Long-term [[Access key]]', 'An ID that starts with `AKIA` plus a secret', 'Until someone deletes it', 'Almost nothing today. Old scripts.'], ['[[Temporary credentials]]', 'An ID that starts with `ASIA`, a secret and a session token', 'Minutes to hours', 'Everything: people through SSO, applications through roles.'], ['[[Bedrock API key]]', 'One long bearer token', 'Short-term: up to 12 hours. Long-term: until the date you choose.', 'Bedrock only. Tools that expect "an API key".']],
          he: [['[[Access key]] ארוך-טווח', 'מזהה שמתחיל ב-`AKIA` ועוד secret', 'עד שמישהו מוחק אותו', 'כמעט כלום היום. סקריפטים ישנים.'], ['[[Temporary credentials]]', 'מזהה שמתחיל ב-`ASIA`, secret ו-session token', 'דקות עד שעות', 'הכול: אנשים דרך SSO, אפליקציות דרך roles.'], ['[[Bedrock API key]]', 'bearer token ארוך אחד', 'קצר-טווח: עד 12 שעות. ארוך-טווח: עד התאריך שבחרת.', 'רק Bedrock. כלים שמצפים ל-"API key".']] } },
        { t: 'h', en: 'People: log in with IAM Identity Center', he: 'אנשים: מתחברים עם IAM Identity Center' },
        { t: 'p', en: 'In a company you normally do not get an [[IAM user]]. You get [[IAM Identity Center]] (people still call it **SSO**). You log in once in the browser with your company login, choose an account and a role, and the CLI receives [[Temporary credentials]] for that role. Setup is one time, login is once a day:', he: 'בחברה בדרך כלל לא מקבלים [[IAM user]]. מקבלים [[IAM Identity Center]] (אנשים עדיין קוראים לזה **SSO**). מתחברים פעם אחת בדפדפן עם ההתחברות של החברה, בוחרים חשבון ו-role, וה-CLI מקבל [[Temporary credentials]] ל-role הזה. ההגדרה חד-פעמית, ההתחברות פעם ביום:' },
        { t: 'code', lang: 'bash', code: '# once: answer the questions, give the profile a name (here: dev)\naws configure sso\n\n# every morning\naws sso login --profile dev\n\n# check who you are now\naws sts get-caller-identity --profile dev', caption: { en: 'The result of `aws configure sso` is a [[Profile]]: a named block in the file `~/.aws/config`.', he: 'התוצאה של `aws configure sso` היא [[Profile]]: בלוק עם שם בקובץ `~/.aws/config`.' } },
        { t: 'code', lang: 'text', code: '# ~/.aws/config\n[profile dev]\nsso_session = acme\nsso_account_id = 123456789012\nsso_role_name = BedrockDeveloper\nregion = us-east-1\n\n[profile prod-readonly]\nsso_session = acme\nsso_account_id = 999988887777\nsso_role_name = ReadOnly\nregion = us-east-1', caption: { en: 'Two profiles: the same person, two accounts, two roles. Notice that no secret is stored in this file.', he: 'שני profiles: אותו אדם, שני חשבונות, שני roles. שים לב שאין שום סוד בקובץ הזה.' } },
        { t: 'p', en: 'The old way is `aws configure`. It asks for an access key ID, a secret access key and a default Region, and writes the keys in plain text to `~/.aws/credentials`. It still works, and you will see it in every old tutorial. On a personal learning account it is acceptable. In a company, prefer SSO.', he: 'הדרך הישנה היא `aws configure`. היא מבקשת access key ID, secret access key ו-Region ברירת מחדל, וכותבת את המפתחות כטקסט רגיל לקובץ `~/.aws/credentials`. זה עדיין עובד, ותראה את זה בכל מדריך ישן. בחשבון למידה אישי זה מקובל. בחברה מעדיפים SSO.' },
        { t: 'h', en: 'Applications: no keys at all', he: 'אפליקציות: בלי מפתחות בכלל' },
        { t: 'p', en: 'Code that runs **on AWS** should never carry keys. You attach an [[IAM role]] to the thing that runs the code: an execution role on a [[Lambda]] function, a task role on a container, an execution role on an agent runtime. The SDK inside finds the temporary credentials of that role by itself and refreshes them before they expire. Your code is just `boto3.client(...)`, with no secrets in it.', he: 'קוד שרץ **על AWS** לא צריך לשאת מפתחות אף פעם. מצמידים [[IAM role]] לדבר שמריץ את הקוד: execution role על פונקציית [[Lambda]], task role על קונטיינר, execution role על סביבת ריצה של סוכן. ה-SDK שבפנים מוצא לבד את ה-credentials הזמניים של ה-role ומרענן אותם לפני שפג תוקפם. הקוד שלך הוא פשוט `boto3.client(...)`, בלי סודות בתוכו.' },
        { t: 'h', en: 'Where the SDK looks, in order', he: 'איפה ה-SDK מחפש, לפי הסדר' },
        { t: 'list', ordered: true, en: ['Values passed in code (never do this with real keys).', 'Environment variables: `AWS_ACCESS_KEY_ID`, `AWS_SECRET_ACCESS_KEY`, `AWS_SESSION_TOKEN`.', 'A profile from `~/.aws/config` and `~/.aws/credentials`: the one named in `AWS_PROFILE`, or else `default`.', 'The role attached to the compute (Lambda, container, EC2).'], he: ['ערכים שהועברו בקוד (לעולם לא עם מפתחות אמיתיים).', 'משתני סביבה: `AWS_ACCESS_KEY_ID`, `AWS_SECRET_ACCESS_KEY`, `AWS_SESSION_TOKEN`.', 'profile מתוך `~/.aws/config` ו-`~/.aws/credentials`: זה ששמו ב-`AWS_PROFILE`, ואם אין אז `default`.', 'ה-role שמוצמד לסביבת הריצה (Lambda, קונטיינר, EC2).'] },
        { t: 'p', en: 'The first place that has credentials wins, and the SDK stops looking. This simple rule explains a whole family of confusing bugs. The Region is found in a similar way: the `region_name` in code, then `AWS_REGION` or `AWS_DEFAULT_REGION`, then the profile.', he: 'המקום הראשון שיש בו credentials מנצח, וה-SDK מפסיק לחפש. הכלל הפשוט הזה מסביר משפחה שלמה של באגים מבלבלים. ה-Region נמצא בדרך דומה: ה-`region_name` בקוד, אחר כך `AWS_REGION` או `AWS_DEFAULT_REGION`, אחר כך ה-profile.' },
        { t: 'quiz', q: { en: 'You ran `aws sso login --profile dev` and it succeeded. But `aws sts get-caller-identity --profile dev` works, while your Python script (no profile in the code) runs as a different, old IAM user. Why?', he: 'הרצת `aws sso login --profile dev` וזה הצליח. `aws sts get-caller-identity --profile dev` עובד, אבל סקריפט ה-Python שלך (בלי profile בקוד) רץ בתור IAM user אחר וישן. למה?' },
          options: { en: ['SSO logins do not work with Python', 'The SSO session has already expired', 'boto3 always prefers IAM users over roles', 'Old `AWS_ACCESS_KEY_ID` and `AWS_SECRET_ACCESS_KEY` variables are still set in the shell, and environment variables win over profiles'], he: ['התחברות SSO לא עובדת עם Python', 'ה-session של SSO כבר פג', 'boto3 תמיד מעדיף IAM users על roles', 'משתני `AWS_ACCESS_KEY_ID` ו-`AWS_SECRET_ACCESS_KEY` ישנים עדיין מוגדרים ב-shell, ומשתני סביבה מנצחים profiles'] },
          answer: 3, explain: { en: 'The script named no profile, so the SDK walked the chain and found keys in the environment first. Fix: `unset` the old variables, and tell the script which profile to use (`AWS_PROFILE=dev` or `boto3.Session(profile_name="dev")`). When identity is confusing, `aws sts get-caller-identity` is always the first command.', he: 'הסקריפט לא ציין profile, אז ה-SDK עבר על השרשרת ומצא קודם מפתחות בסביבה. התיקון: `unset` למשתנים הישנים, ולהגיד לסקריפט באיזה profile להשתמש (`AWS_PROFILE=dev` או `boto3.Session(profile_name="dev")`). כשהזהות מבלבלת, `aws sts get-caller-identity` היא תמיד הפקודה הראשונה.' } },
        { t: 'fill', prompt: { en: 'Make this script use the `dev` profile explicitly, so it does not depend on what is set in the shell.', he: 'גרום לסקריפט הזה להשתמש ב-profile בשם `dev` במפורש, כך שהוא לא יהיה תלוי במה שמוגדר ב-shell.' },
          lang: 'python', code: 'import boto3\n\nsession = boto3.{{1}}({{2}}="dev")\nclient = session.client("bedrock-runtime", region_name="us-east-1")', blanks: [ { accept: ['Session'], hint: { en: 'the boto3 object that holds credentials and settings', he: 'האובייקט של boto3 שמחזיק credentials והגדרות' } }, { accept: ['profile_name'], hint: { en: 'the argument that names a profile', he: 'הארגומנט שנותן שם של profile' } } ],
          explain: { en: 'A `Session` is where boto3 keeps the credentials and Region. `boto3.client(...)` uses a hidden default session. On your laptop an explicit profile avoids surprises. In code that runs on AWS, do not name a profile: let the SDK find the attached role.', he: '`Session` הוא המקום שבו boto3 שומר את ה-credentials וה-Region. `boto3.client(...)` משתמש ב-session ברירת מחדל נסתר. על הלפטופ, profile מפורש מונע הפתעות. בקוד שרץ על AWS לא מציינים profile: נותנים ל-SDK למצוא את ה-role המוצמד.' } },
        { t: 'terminal', title: { en: 'Lab: who am I, and can I see Bedrock?', he: 'מעבדה: מי אני, והאם אני רואה את Bedrock?' }, intro: { en: 'A new laptop, a new company. Your SSO profile is called `dev`. Check your identity and then look at Bedrock from the command line.', he: 'לפטופ חדש, חברה חדשה. ה-profile של SSO שלך נקרא `dev`. בדוק את הזהות שלך ואז הסתכל על Bedrock משורת הפקודה.' }, shell: 'bash — ~',
          steps: [
            { ask: { en: 'First see what the CLI is configured with right now: which profile, where the keys come from, which Region.', he: 'קודם ראה עם מה ה-CLI מוגדר כרגע: איזה profile, מאיפה המפתחות מגיעים, איזה Region.' }, accept: ['^aws\\s+configure\\s+list(\\s+--profile[\\s=]\\S+)?$'], hint: 'aws configure list', output: '      Name                    Value             Type    Location\n      ----                    -----             ----    --------\n   profile                <not set>             None    None\naccess_key                <not set>             None    None\nsecret_key                <not set>             None    None\n    region                <not set>             None    None' },
            { ask: { en: 'Nothing is set. Log in through SSO with the profile `dev`.', he: 'כלום לא מוגדר. התחבר דרך SSO עם ה-profile בשם `dev`.' }, accept: ['^aws\\s+sso\\s+login\\s+--profile[\\s=]dev$'], hint: 'aws sso login --profile dev', output: 'Attempting to automatically open the SSO authorization page in your default browser.\nSuccessfully logged into Start URL: https://acme.awsapps.com/start' },
            { ask: { en: 'Ask AWS who you are when you use the profile `dev`.', he: 'שאל את AWS מי אתה כשאתה משתמש ב-profile בשם `dev`.' }, accept: ['^aws\\s+sts\\s+get-caller-identity\\s+--profile[\\s=]dev$', '^aws\\s+--profile[\\s=]dev\\s+sts\\s+get-caller-identity$'], hint: 'aws sts get-caller-identity --profile dev', output: '{\n    "UserId": "AROAEXAMPLEID:dana",\n    "Account": "123456789012",\n    "Arn": "arn:aws:sts::123456789012:assumed-role/BedrockDeveloper/dana"\n}', wrong: 'Unable to locate credentials. You can configure credentials by running "aws configure".' },
            { ask: { en: 'Typing `--profile dev` every time is tiring. Set the environment variable that makes `dev` the profile for this shell.', he: 'להקליד `--profile dev` בכל פעם זה מעייף. הגדר את משתנה הסביבה שהופך את `dev` ל-profile של ה-shell הזה.' }, accept: ['^export\\s+AWS_PROFILE=\\W?dev\\W?$'], hint: 'export AWS_PROFILE=dev', output: '' },
            { ask: { en: 'List the foundation models that Bedrock offers in `us-east-1`.', he: 'הצג את ה-foundation models ש-Bedrock מציע ב-`us-east-1`.' }, accept: ['^aws\\s+bedrock\\s+list-foundation-models\\b.*--region[\\s=]us-east-1\\b', '^aws\\s+--region[\\s=]us-east-1\\s+bedrock\\s+list-foundation-models\\b'], hint: 'aws bedrock list-foundation-models --region us-east-1', output: '{\n    "modelSummaries": [\n        {\n            "modelId": "amazon.nova-2-lite-v1:0",\n            "providerName": "Amazon",\n            ...\n        },\n        ...\n    ]\n}', wrong: 'Hint: the service is "bedrock" (not bedrock-runtime) and the Region must be us-east-1.' },
            { ask: { en: 'Now list the inference profiles in the same Region (you will learn what they are in module 3).', he: 'עכשיו הצג את ה-inference profiles באותו Region (תלמד מה הם במודול 3).' }, accept: ['^aws\\s+bedrock\\s+list-inference-profiles\\b'], hint: 'aws bedrock list-inference-profiles --region us-east-1', output: '{\n    "inferenceProfileSummaries": [\n        {\n            "inferenceProfileId": "us.anthropic.claude-sonnet-4-6",\n            "status": "ACTIVE",\n            ...\n        },\n        ...\n    ]\n}' }
          ],
          done: { en: 'You checked the configuration, logged in, confirmed your identity and made two read-only calls to the Bedrock control plane. If the last two had failed with AccessDeniedException, you would now know exactly which role to look at.', he: 'בדקת את ההגדרות, התחברת, אימתת את הזהות שלך וביצעת שתי קריאות לקריאה בלבד ל-control plane של Bedrock. אם שתי האחרונות היו נכשלות עם AccessDeniedException, היית יודע עכשיו בדיוק על איזה role להסתכל.' } },
        { t: 'h', en: 'Bedrock API keys', he: 'Bedrock API keys' },
        { t: 'p', en: 'Many AI tools and SDKs (for example the OpenAI SDK) expect one string called "an API key", not AWS signatures. For them Bedrock has the [[Bedrock API key]]: a bearer token that you send in a header instead of signing the request. There are two kinds, and the difference is important.', he: 'הרבה כלי AI ו-SDKs (למשל ה-SDK של OpenAI) מצפים למחרוזת אחת שנקראת "API key", לא לחתימות של AWS. בשבילם יש ל-Bedrock את ה-[[Bedrock API key]]: bearer token ששולחים ב-header במקום לחתום על הבקשה. יש שני סוגים, וההבדל חשוב.' },
        { t: 'table', head: { en: ['', 'Short-term key', 'Long-term key'], he: ['', 'מפתח קצר-טווח', 'מפתח ארוך-טווח'] }, rows: {
          en: [['Lives for', 'Up to 12 hours, or until your session ends, whichever is shorter', 'Until an expiry date that you choose'], ['Permissions', 'The same as the principal that generated it', 'Creates an IAM user with policies attached (by default `AmazonBedrockLimitedAccess`)'], ['Where it works', 'Only in the Region where it was generated', 'Check the docs for the exact scope'], ['AWS says', '"Recommended for production use"', '"Recommended only for exploration"'], ['How to get it', 'Console, or in code with the `aws-bedrock-token-generator` package', 'Console, or the IAM API']],
          he: [['כמה זמן חי', 'עד 12 שעות, או עד שה-session שלך נגמר, הקצר מביניהם', 'עד תאריך תפוגה שאתה בוחר'], ['הרשאות', 'כמו של ה-principal שיצר אותו', 'יוצר IAM user עם policies מוצמדות (ברירת מחדל: `AmazonBedrockLimitedAccess`)'], ['איפה עובד', 'רק ב-Region שבו הוא נוצר', 'בדוק בתיעוד את ההיקף המדויק'], ['AWS אומרת', '"Recommended for production use"', '"Recommended only for exploration"'], ['איך משיגים', 'בקונסול, או בקוד עם החבילה `aws-bedrock-token-generator`', 'בקונסול, או דרך ה-API של IAM']] } },
        { t: 'code', lang: 'bash', code: 'export AWS_BEARER_TOKEN_BEDROCK=<api-key>\n\ncurl -X POST "https://bedrock-runtime.us-east-1.amazonaws.com/model/us.anthropic.claude-sonnet-4-6/converse" \\\n  -H "Content-Type: application/json" \\\n  -H "Authorization: Bearer $AWS_BEARER_TOKEN_BEDROCK" \\\n  -d \'{"messages": [{"role": "user", "content": [{"text": "Hello"}]}]}\'', caption: { en: 'A model call with nothing but curl and a key. boto3 (version 1.39.0 or later) also picks up the `AWS_BEARER_TOKEN_BEDROCK` variable by itself.', he: 'קריאה למודל רק עם curl ומפתח. גם boto3 (גרסה 1.39.0 ומעלה) קולט לבד את המשתנה `AWS_BEARER_TOKEN_BEDROCK`.' } },
        { t: 'console', service: 'Amazon Bedrock', nav: ['Model catalog', 'Chat / Text playground', 'API keys', 'Settings'], active: 'API keys', crumbs: ['Amazon Bedrock', 'API keys'],
          heading: 'API keys',
          panels: [
            { title: 'Short-term API keys', n: 1, text: 'Generate short-term API keys' },
            { title: 'Long-term API keys', n: 2, text: 'Generate long-term API keys', fields: [ { label: 'Advanced permissions', type: 'text', value: 'optional', n: 3 } ], table: { cols: ['Key actions'], rows: [['Deactivate'], ['Reset key'], ['Delete'], ['Manage in IAM Console']] } }
          ],
          callouts: [
            { n: 1, en: 'The tab for keys that live up to 12 hours and carry your own permissions. This is the one to prefer.', he: 'הלשונית למפתחות שחיים עד 12 שעות ונושאים את ההרשאות שלך. את זה מעדיפים.' },
            { n: 2, en: 'The tab for keys with an expiry date that you choose. Behind each one, AWS creates an IAM user. The table shows what you can do with an existing key.', he: 'הלשונית למפתחות עם תאריך תפוגה שאתה בוחר. מאחורי כל אחד, AWS יוצרת IAM user. הטבלה מראה מה אפשר לעשות עם מפתח קיים.' },
            { n: 3, en: 'Here you can change which policies the key\'s IAM user gets.', he: 'כאן אפשר לשנות אילו policies ה-IAM user של המפתח מקבל.' }
          ],
          caption: { en: 'The API keys page of the Bedrock console, simplified. In the real console the two kinds are two tabs.', he: 'דף ה-API keys בקונסול של Bedrock, בצורה מפושטת. בקונסול האמיתי שני הסוגים הם שתי לשוניות.' } },
        { t: 'note', kind: 'warn', en: 'An API key is not a magic pass. It only says **who** is calling. The principal behind the key still needs `bedrock:InvokeModel` and the rest, exactly like with normal credentials. Using a key is itself an IAM action (`bedrock:CallWithBearerToken`), so a company can forbid keys completely with one Deny. Calls made with a key appear in [[CloudTrail]]. The key itself is not logged.', he: 'API key הוא לא כרטיס קסם. הוא רק אומר **מי** קורא. ה-principal שמאחורי המפתח עדיין צריך `bedrock:InvokeModel` וכל השאר, בדיוק כמו עם credentials רגילים. השימוש במפתח הוא בעצמו פעולת IAM (`bedrock:CallWithBearerToken`), כך שחברה יכולה לאסור מפתחות לגמרי עם Deny אחד. קריאות שנעשו עם מפתח מופיעות ב-[[CloudTrail]]. המפתח עצמו לא נרשם.' },
        { t: 'quiz', q: { en: 'You need a Bedrock API key for a service that runs in production. Which one do you choose, following the AWS recommendation?', he: 'אתה צריך Bedrock API key לשירות שרץ ב-production. איזה בוחרים, לפי ההמלצה של AWS?' },
          options: { en: ['A long-term key with no expiry, so the service never breaks', 'A short-term key that the service generates for itself from its role and renews', 'A long-term key committed to the private repository', 'The access key of the account administrator'], he: ['מפתח ארוך-טווח בלי תפוגה, כדי שהשירות לא יישבר אף פעם', 'מפתח קצר-טווח שהשירות יוצר לעצמו מתוך ה-role שלו ומחדש', 'מפתח ארוך-טווח שנשמר ב-repository הפרטי', 'ה-access key של מנהל החשבון'] },
          answer: 1, explain: { en: 'AWS marks short-term keys as "recommended for production use" and long-term keys as "recommended only for exploration". A short-term key comes from the service\'s own role (with the token generator package), lives at most 12 hours, and has exactly the role\'s permissions. A long-term key is a secret that sits somewhere and waits to leak.', he: 'AWS מסמנת מפתחות קצרי-טווח כ-"recommended for production use" וארוכי-טווח כ-"recommended only for exploration". מפתח קצר-טווח נוצר מה-role של השירות עצמו (עם חבילת ה-token generator), חי לכל היותר 12 שעות, ויש לו בדיוק את ההרשאות של ה-role. מפתח ארוך-טווח הוא סוד שיושב איפשהו ומחכה לדלוף.' } },
        { t: 'quiz', q: { en: 'A developer generates a short-term API key from a role that can only read S3. A Bedrock call with this key fails with AccessDeniedException. Why?', he: 'מפתח יוצר API key קצר-טווח מתוך role שיכול רק לקרוא S3. קריאה ל-Bedrock עם המפתח הזה נכשלת עם AccessDeniedException. למה?' },
          options: { en: ['The key carries the permissions of the role that generated it, and that role may not invoke models', 'Short-term keys cannot call models, only list them', 'The key needs 15 minutes to become active', 'API keys work only with the OpenAI SDK'], he: ['המפתח נושא את ההרשאות של ה-role שיצר אותו, ול-role הזה אסור להפעיל מודלים', 'מפתחות קצרי-טווח לא יכולים לקרוא למודלים, רק להציג אותם', 'המפתח צריך 15 דקות כדי להפוך לפעיל', 'API keys עובדים רק עם ה-SDK של OpenAI'] },
          answer: 0, explain: { en: 'A key does not grant access by itself. A short-term key inherits the permissions of the principal that generated it. No `bedrock:InvokeModel` on the role means no model calls with the key.', he: 'מפתח לא נותן גישה בעצמו. מפתח קצר-טווח יורש את ההרשאות של ה-principal שיצר אותו. אין `bedrock:InvokeModel` על ה-role, אין קריאות למודל עם המפתח.' } },
        { t: 'h', en: 'Never commit secrets', he: 'אף פעם לא עושים commit לסודות' },
        { t: 'p', en: 'Bots scan public repositories for AWS keys all the time. A leaked key is found in minutes, and then someone else runs expensive models on your bill. The rules are simple:', he: 'בוטים סורקים repositories ציבוריים בחיפוש אחרי מפתחות AWS כל הזמן. מפתח שדלף נמצא בתוך דקות, ואז מישהו אחר מריץ מודלים יקרים על החשבון שלך. הכללים פשוטים:' },
        { t: 'list', en: ['No keys in code, in notebooks, in screenshots, in chat. A private repository is not a safe place either.', 'On your laptop: SSO profiles. On AWS: roles. Then there is nothing to leak.', 'If a tool must have a key, put it in an environment variable or a secrets store, and add `.env` to `.gitignore`.', 'If a secret leaked: deactivate or delete it **first**, then create a new one, then check [[CloudTrail]] for what it was used for. Deleting the commit is not enough, because the key is already copied.'], he: ['אין מפתחות בקוד, ב-notebooks, בצילומי מסך, בצ׳אט. גם repository פרטי הוא לא מקום בטוח.', 'על הלפטופ: profiles של SSO. על AWS: roles. ואז אין מה שידלוף.', 'אם כלי חייב מפתח, שמים אותו במשתנה סביבה או במאגר סודות, ומוסיפים `.env` ל-`.gitignore`.', 'אם סוד דלף: **קודם** משביתים או מוחקים אותו, אחר כך יוצרים חדש, ואז בודקים ב-[[CloudTrail]] למה הוא שימש. למחוק את ה-commit לא מספיק, כי המפתח כבר הועתק.'] },
        { t: 'fill', prompt: { en: 'A tool reads its Bedrock API key from the environment. Set the variable that boto3 and the Bedrock docs use for it.', he: 'כלי קורא את ה-Bedrock API key שלו מהסביבה. הגדר את המשתנה ש-boto3 והתיעוד של Bedrock משתמשים בו.' },
          lang: 'bash', code: 'export {{1}}=<api-key>\npython app.py', blanks: [ { accept: ['AWS_BEARER_TOKEN_BEDROCK'], hint: { en: 'AWS_ + the kind of token + the service', he: 'AWS_ + סוג ה-token + השירות' } } ],
          explain: { en: '`AWS_BEARER_TOKEN_BEDROCK` is the variable name. With the OpenAI SDK you put the same key in `OPENAI_API_KEY` instead. Either way the value stays in the environment and out of the code.', he: '`AWS_BEARER_TOKEN_BEDROCK` הוא שם המשתנה. עם ה-SDK של OpenAI שמים את אותו מפתח ב-`OPENAI_API_KEY` במקום. בשני המקרים הערך נשאר בסביבה ולא בקוד.' } },
        { t: 'reveal', q: { en: 'A teammate pasted a long-term access key into the team chat "just for a minute". What do you do, and what do you say?', he: 'חבר צוות הדביק access key ארוך-טווח בצ׳אט של הצוות "רק לדקה". מה אתה עושה, ומה אתה אומר?' },
          a: { en: 'Treat it as leaked, because chat history is stored and searchable. Deactivate or delete that key right now, create a new one only if it is really needed, and look in CloudTrail at what the key did recently. Then fix the cause: why did a person need a long-term key at all? Usually the answer is to move the person to SSO and the script to a role, so that next time there is no key to paste.', he: 'מתייחסים לזה כאל דליפה, כי היסטוריית הצ׳אט נשמרת וניתנת לחיפוש. משביתים או מוחקים את המפתח עכשיו, יוצרים חדש רק אם באמת צריך, ובודקים ב-CloudTrail מה המפתח עשה לאחרונה. אחר כך מתקנים את הסיבה: למה אדם בכלל היה צריך מפתח ארוך-טווח? בדרך כלל התשובה היא להעביר את האדם ל-SSO ואת הסקריפט ל-role, כך שבפעם הבאה לא יהיה מפתח להדביק.' } }
      ]
    },
    {
      id: 'm02l4', minutes: 13,
      title: { en: 'The supporting cast: the services around Bedrock', he: 'שחקני המשנה: השירותים שמסביב ל-Bedrock' },
      blocks: [
        { t: 'p', en: 'A GenAI application is never only a model call. Around the model there are always the same few AWS services. You do not need to be an expert in any of them. You need to know what each one is, why it shows up in your project, and what breaks when it is set up wrong.', he: 'אפליקציית GenAI היא אף פעם לא רק קריאה למודל. מסביב למודל יש תמיד אותם כמה שירותים של AWS. לא צריך להיות מומחה באף אחד מהם. צריך לדעת מה כל אחד, למה הוא מופיע בפרויקט שלך, ומה נשבר כשהוא מוגדר לא נכון.' },
        { t: 'arch', layers: [
          { title: { en: 'Your code', he: 'הקוד שלך' }, items: ['Lambda', { en: 'Container or agent runtime', he: 'קונטיינר או סביבת ריצה של סוכן' }] },
          { title: { en: 'Models', he: 'מודלים' }, items: ['Amazon Bedrock'] },
          { title: { en: 'Data', he: 'מידע' }, items: [{ en: 'S3: documents, batch files, logs', he: 'S3: מסמכים, קבצי batch, לוגים' }] },
          { title: { en: 'Around everything', he: 'מסביב להכול' }, items: ['IAM', 'KMS', 'VPC + PrivateLink', 'CloudWatch', 'CloudTrail', 'Service Quotas'] }
        ], caption: { en: 'The usual picture. The bottom layer touches every other layer.', he: 'התמונה הרגילה. השכבה התחתונה נוגעת בכל שכבה אחרת.' } },
        { t: 'table', head: { en: ['Service', 'What it is', 'Why a GenAI developer meets it'], he: ['שירות', 'מה זה', 'למה מפתח GenAI פוגש אותו'] }, rows: {
          en: [['[[S3]]', 'File storage. Files ("objects") live in a "bucket".', 'Documents for [[RAG]], input and output files of batch jobs, training data, saved model logs.'], ['[[Lambda]]', 'Runs a function when it is called. No server.', 'The code behind an agent\'s tools, small APIs in front of a model, glue code.'], ['[[CloudWatch]]', 'Metrics, logs and alarms.', 'Token counts, latency, errors and throttles of your model calls. Full prompts and answers, if you turn that on.'], ['[[VPC]] and [[PrivateLink]]', 'Your private network, and a private door from it to an AWS service.', 'Companies that do not allow model traffic over the public internet.'], ['[[KMS]]', 'Encryption keys.', 'Encrypting knowledge bases, custom models, guardrails and logs with a key that the company controls.'], ['[[CloudTrail]]', 'The audit log of API calls.', 'Who called which model, when, with which role.'], ['Service Quotas', 'The place where account limits are shown and raised.', 'Tokens-per-minute limits per model. The source of [[Throttling]].']],
          he: [['[[S3]]', 'אחסון קבצים. קבצים ("objects") חיים בתוך "bucket".', 'מסמכים ל-[[RAG]], קבצי קלט ופלט של עבודות batch, מידע לאימון, לוגים שמורים של מודלים.'], ['[[Lambda]]', 'מריץ פונקציה כשקוראים לה. בלי שרת.', 'הקוד שמאחורי הכלים של סוכן, APIs קטנים לפני מודל, קוד דבק.'], ['[[CloudWatch]]', 'Metrics, לוגים ו-alarms.', 'ספירות טוקנים, latency, שגיאות ו-throttles של הקריאות למודל. פרומפטים ותשובות מלאים, אם מדליקים את זה.'], ['[[VPC]] ו-[[PrivateLink]]', 'הרשת הפרטית שלך, ודלת פרטית ממנה לשירות של AWS.', 'חברות שלא מרשות תעבורת מודלים דרך האינטרנט הציבורי.'], ['[[KMS]]', 'מפתחות הצפנה.', 'הצפנת knowledge bases, מודלים מותאמים, guardrails ולוגים עם מפתח שהחברה שולטת בו.'], ['[[CloudTrail]]', 'יומן הביקורת של קריאות API.', 'מי קרא לאיזה מודל, מתי, עם איזה role.'], ['Service Quotas', 'המקום שבו רואים ומעלים את מגבלות החשבון.', 'מגבלות טוקנים לדקה לכל מודל. המקור של [[Throttling]].']] } },
        { t: 'h', en: 'S3 and Lambda: where your data and your code sit', he: 'S3 ו-Lambda: איפה המידע והקוד שלך יושבים' },
        { t: 'p', en: 'In [[S3]] you address a file as `s3://bucket-name/path/to/file.pdf`. Many Bedrock features read from S3 or write to it: a knowledge base reads your documents from a bucket, a batch job reads a `.jsonl` file of prompts and writes the answers next to it, and model logs can be delivered there. The thing to remember: **Bedrock needs permission to your bucket**. That is usually a [[Service role]] that Bedrock assumes, or a bucket policy that names the Bedrock service. "The job failed immediately" is very often this.', he: 'ב-[[S3]] פונים לקובץ כך: `s3://bucket-name/path/to/file.pdf`. הרבה יכולות של Bedrock קוראות מ-S3 או כותבות אליו: knowledge base קורא את המסמכים שלך מ-bucket, עבודת batch קוראת קובץ `.jsonl` של פרומפטים וכותבת את התשובות לידו, ואפשר לשלוח לשם לוגים של מודלים. מה שצריך לזכור: **Bedrock צריך הרשאה ל-bucket שלך**. בדרך כלל זה [[Service role]] ש-Bedrock לוקח, או bucket policy שמציינת את שירות Bedrock. "העבודה נכשלה מיד" זה לעיתים קרובות מאוד בדיוק זה.' },
        { t: 'p', en: 'A [[Lambda]] function is your code plus an execution role. When an agent decides to use a tool such as "look up order status", very often a Lambda function is what really runs. Two things break here: the execution role lacks a permission (the last lesson), or the function runs longer than its configured timeout.', he: 'פונקציית [[Lambda]] היא הקוד שלך ועוד execution role. כשסוכן מחליט להשתמש בכלי כמו "בדוק סטטוס הזמנה", לעיתים קרובות מאוד מה שבאמת רץ הוא פונקציית Lambda. שני דברים נשברים כאן: ל-execution role חסרה הרשאה (השיעור הקודם), או שהפונקציה רצה יותר מה-timeout שהוגדר לה.' },
        { t: 'h', en: 'CloudWatch, CloudTrail and model invocation logging', he: 'CloudWatch, CloudTrail ו-model invocation logging' },
        { t: 'p', en: 'These three get mixed up all the time, and interviewers love to ask about them.', he: 'מתבלבלים בין שלושת אלה כל הזמן, ומראיינים אוהבים לשאול עליהם.' },
        { t: 'table', head: { en: ['', 'Answers the question', 'On by default?', 'Contains the prompt text?'], he: ['', 'עונה על השאלה', 'דולק כברירת מחדל?', 'מכיל את טקסט הפרומפט?'] }, rows: {
          en: [['[[CloudWatch]] metrics', 'How many calls, how many tokens, how slow, how many errors?', 'Yes', 'No, only numbers'], ['[[CloudTrail]]', 'Who called which API, when, with which role?', 'Yes, for the calls that matter here', 'No. It records the call and the model ID, not the prompt.'], ['[[Model invocation logging]]', 'What exactly was sent and what came back?', '**No**', 'Yes, the full request and response']],
          he: [['Metrics של [[CloudWatch]]', 'כמה קריאות, כמה טוקנים, כמה איטי, כמה שגיאות?', 'כן', 'לא, רק מספרים'], ['[[CloudTrail]]', 'מי קרא לאיזה API, מתי, עם איזה role?', 'כן, לקריאות שחשובות כאן', 'לא. הוא רושם את הקריאה ואת ה-model ID, לא את הפרומפט.'], ['[[Model invocation logging]]', 'מה בדיוק נשלח ומה חזר?', '**לא**', 'כן, הבקשה והתשובה המלאות']] } },
        { t: 'p', en: 'Bedrock sends its metrics to CloudWatch under the namespace `AWS/Bedrock`. The ones you will look at most: `Invocations`, `InvocationLatency`, `InvocationThrottles`, `InputTokenCount`, `OutputTokenCount`, and `TimeToFirstToken` for streaming calls. [[Model invocation logging]] is a setting per account and per Region. It can deliver to CloudWatch Logs, to S3, or to both. Because it stores real prompts, the place where it writes becomes sensitive data: decide who can read it before you turn it on.', he: 'Bedrock שולח את ה-metrics שלו ל-CloudWatch תחת ה-namespace בשם `AWS/Bedrock`. אלה שתסתכל עליהם הכי הרבה: `Invocations`, `InvocationLatency`, `InvocationThrottles`, `InputTokenCount`, `OutputTokenCount`, ו-`TimeToFirstToken` לקריאות streaming. [[Model invocation logging]] היא הגדרה לכל חשבון ולכל Region. היא יכולה לשלוח ל-CloudWatch Logs, ל-S3 או לשניהם. מכיוון שהיא שומרת פרומפטים אמיתיים, המקום שאליו היא כותבת הופך למידע רגיש: מחליטים מי יכול לקרוא אותו לפני שמדליקים.' },
        { t: 'quiz', q: { en: 'The security team asks: "Which role called a Bedrock model at 03:00 last night?" Where do you look?', he: 'צוות האבטחה שואל: "איזה role קרא למודל של Bedrock ב-03:00 אתמול בלילה?" איפה מחפשים?' },
          options: { en: ['CloudWatch metrics', 'The S3 bucket with the documents', 'CloudTrail', 'Service Quotas'], he: ['Metrics של CloudWatch', 'ה-S3 bucket עם המסמכים', 'CloudTrail', 'Service Quotas'] },
          answer: 2, explain: { en: '"Who did what, when" is always CloudTrail. Metrics would only show that there were calls, not who made them. If the next question is "and what was the prompt?", CloudTrail cannot answer. Only model invocation logging can, and only if it was turned on before.', he: '"מי עשה מה ומתי" זה תמיד CloudTrail. Metrics רק יראו שהיו קריאות, לא מי ביצע אותן. אם השאלה הבאה היא "ומה היה הפרומפט?", CloudTrail לא יכול לענות. רק model invocation logging יכול, ורק אם הדליקו אותו קודם.' } },
        { t: 'console', service: 'Amazon Bedrock', nav: ['Model catalog', 'Chat / Text playground', 'API keys', 'Settings'], active: 'Settings', crumbs: ['Amazon Bedrock', 'Settings'],
          task: { en: 'Your team wants to keep every **text** prompt and answer for later analysis, in cheap long-term storage, with no copy in CloudWatch Logs. Turn on model invocation logging for text only, with the right destination.', he: 'הצוות שלך רוצה לשמור כל פרומפט ותשובה של **טקסט** לניתוח מאוחר יותר, באחסון זול לטווח ארוך, בלי עותק ב-CloudWatch Logs. הדלק model invocation logging לטקסט בלבד, עם היעד הנכון.' },
          heading: 'Settings',
          panels: [
            { title: 'Model invocation logging', n: 1, fields: [
              { label: 'Model invocation logging', type: 'toggle', value: false, expect: true, hint: { en: 'Logging is off by default. Turn it on.', he: 'הלוגים כבויים כברירת מחדל. הדלק אותם.' } },
              { label: 'Text', type: 'toggle', value: false, expect: true, n: 2, hint: { en: 'The team wants text prompts and answers.', he: 'הצוות רוצה פרומפטים ותשובות של טקסט.' } },
              { label: 'Image', type: 'toggle', value: false, expect: false, hint: { en: 'Only text was asked for.', he: 'ביקשו רק טקסט.' } },
              { label: 'Embedding', type: 'toggle', value: false, expect: false, hint: { en: 'Only text was asked for.', he: 'ביקשו רק טקסט.' } },
              { label: 'Video', type: 'toggle', value: false, expect: false, hint: { en: 'Only text was asked for.', he: 'ביקשו רק טקסט.' } },
              { label: 'Logging destinations', type: 'radio', options: ['CloudWatch Logs only', 'Amazon S3 only', 'Both Amazon S3 and CloudWatch Logs'], value: 'CloudWatch Logs only', expect: 'Amazon S3 only', n: 3, hint: { en: 'Cheap long-term file storage, and no copy in CloudWatch Logs.', he: 'אחסון קבצים זול לטווח ארוך, ובלי עותק ב-CloudWatch Logs.' } }
            ] }
          ],
          buttons: ['Cancel', 'Save settings'],
          callouts: [
            { n: 1, en: 'One switch for the whole account in this Region. It covers Converse and InvokeModel calls, with and without streaming.', he: 'מתג אחד לכל החשבון ב-Region הזה. הוא מכסה קריאות Converse ו-InvokeModel, עם ובלי streaming.' },
            { n: 2, en: 'You choose which kinds of data to log. Images and large bodies are heavy, so they are stored as separate objects in S3.', he: 'בוחרים אילו סוגי מידע לרשום. תמונות וגופי בקשה גדולים הם כבדים, ולכן נשמרים כ-objects נפרדים ב-S3.' },
            { n: 3, en: 'S3 is cheap and good for analysis in bulk. CloudWatch Logs is better for searching live. The destination must be in the same account and Region.', he: 'S3 זול וטוב לניתוח בכמויות. CloudWatch Logs טוב יותר לחיפוש חי. היעד חייב להיות באותו חשבון ו-Region.' }
          ],
          success: { en: 'Logging is on. From now on every text request and response in this Region is saved to S3. In the real console you also choose the bucket, and the bucket policy must allow the Bedrock service to write into it.', he: 'הלוגים דולקים. מעכשיו כל בקשה ותשובה של טקסט ב-Region הזה נשמרות ל-S3. בקונסול האמיתי בוחרים גם את ה-bucket, וה-bucket policy חייבת להרשות לשירות Bedrock לכתוב אליו.' },
          caption: { en: 'Settings page of the Bedrock console, simplified: the real screen also asks for the bucket or the log group.', he: 'דף ה-Settings בקונסול של Bedrock, בצורה מפושטת: המסך האמיתי מבקש גם את ה-bucket או את ה-log group.' } },
        { t: 'quiz', q: { en: 'You turned on model invocation logging in `us-east-1`. A week later you look for the logs of your application and find nothing. The application calls models in `us-west-2`. What happened?', he: 'הדלקת model invocation logging ב-`us-east-1`. שבוע אחר כך אתה מחפש את הלוגים של האפליקציה ולא מוצא כלום. האפליקציה קוראת למודלים ב-`us-west-2`. מה קרה?' },
          options: { en: ['Logging is a setting per Region, and it was never turned on in us-west-2', 'Logs appear only after 30 days', 'Logging works only for calls from the console', 'The application must pass a "log this" flag on every call'], he: ['הלוגים הם הגדרה לכל Region, והם מעולם לא הודלקו ב-us-west-2', 'לוגים מופיעים רק אחרי 30 יום', 'הלוגים עובדים רק לקריאות מהקונסול', 'האפליקציה חייבת להעביר דגל "רשום את זה" בכל קריאה'] },
          answer: 0, explain: { en: 'The setting is per account **and per Region**. Nothing is logged in a Region where it is off, and old calls are never logged afterwards. Turn it on in every Region your application calls, before you need it.', he: 'ההגדרה היא לכל חשבון **ולכל Region**. שום דבר לא נרשם ב-Region שבו היא כבויה, וקריאות ישנות לא נרשמות בדיעבד. מדליקים אותה בכל Region שהאפליקציה קוראת אליו, לפני שצריכים אותה.' } },
        { t: 'h', en: 'VPC, PrivateLink and KMS: what the security review asks for', he: 'VPC, PrivateLink ו-KMS: מה שסקירת האבטחה מבקשת' },
        { t: 'p', en: 'By default your code reaches Bedrock at a public address, encrypted with TLS (Bedrock requires TLS 1.2 and recommends 1.3). Banks, hospitals and many enterprises want more: the traffic must not leave their private network. For this you create a **VPC interface endpoint** ([[PrivateLink]]) for the service `com.amazonaws.<region>.bedrock-runtime` inside your [[VPC]]. With the option **Enable Private DNS Name** turned on, your code does not change at all: the normal Bedrock address now resolves to the private door.', he: 'כברירת מחדל הקוד שלך מגיע ל-Bedrock בכתובת ציבורית, מוצפן עם TLS (Bedrock דורש TLS 1.2 וממליץ על 1.3). בנקים, בתי חולים והרבה ארגונים גדולים רוצים יותר: שהתעבורה לא תצא מהרשת הפרטית שלהם. בשביל זה יוצרים **VPC interface endpoint** ([[PrivateLink]]) לשירות `com.amazonaws.<region>.bedrock-runtime` בתוך ה-[[VPC]] שלך. כשהאפשרות **Enable Private DNS Name** דולקת, הקוד שלך לא משתנה בכלל: הכתובת הרגילה של Bedrock מפנה עכשיו לדלת הפרטית.' },
        { t: 'p', en: 'Stored data on AWS is encrypted anyway. [[KMS]] becomes your topic when the company wants a **customer managed key**: a key that the company owns, can audit and can switch off. Bedrock supports such keys for things like custom models, knowledge bases and guardrails. The practical point for you: when a resource is encrypted with such a key, every role that touches it also needs permission to use the key. A missing key permission looks like one more mysterious AccessDenied.', he: 'מידע שמור ב-AWS מוצפן בכל מקרה. [[KMS]] הופך לנושא שלך כשהחברה רוצה **customer managed key**: מפתח שהחברה היא הבעלים שלו, יכולה לבקר אותו ויכולה לכבות אותו. Bedrock תומך במפתחות כאלה לדברים כמו מודלים מותאמים, knowledge bases ו-guardrails. הנקודה המעשית בשבילך: כשמשאב מוצפן במפתח כזה, כל role שנוגע בו צריך גם הרשאה להשתמש במפתח. הרשאת מפתח חסרה נראית כמו עוד AccessDenied מסתורי.' },
        { t: 'quiz', q: { en: 'A bank will approve your project only if model traffic never crosses the public internet. What do you add?', he: 'בנק יאשר את הפרויקט שלך רק אם תעבורת המודלים לא עוברת אף פעם באינטרנט הציבורי. מה מוסיפים?' },
          options: { en: ['A customer managed KMS key', 'Model invocation logging', 'A bigger quota', 'A VPC interface endpoint (PrivateLink) for bedrock-runtime'], he: ['מפתח KMS בניהול הלקוח', 'Model invocation logging', 'quota גדולה יותר', 'VPC interface endpoint (PrivateLink) ל-bedrock-runtime'] },
          answer: 3, explain: { en: 'PrivateLink is about the **network path**. KMS is about encryption of stored data, which is a different requirement (the bank will probably ask for that too). Do not confuse "encrypted" with "private path": the default traffic is already encrypted, but it goes to a public address.', he: 'PrivateLink עוסק ב**נתיב הרשת**. KMS עוסק בהצפנה של מידע שמור, וזו דרישה אחרת (הבנק כנראה יבקש גם אותה). לא מבלבלים בין "מוצפן" לבין "נתיב פרטי": התעבורה הרגילה כבר מוצפנת, אבל היא הולכת לכתובת ציבורית.' } },
        { t: 'h', en: 'Quotas and throttling', he: 'Quotas ו-throttling' },
        { t: 'p', en: 'AWS protects shared capacity with limits called [[Quota]]s. For Bedrock the main ones count **tokens per minute** for each model, per account and per Region. You see them in the **Service Quotas** console under the service "Amazon Bedrock". When your application goes over a quota, AWS rejects the extra requests with a `ThrottlingException` (HTTP 429). That is [[Throttling]].', he: 'AWS מגינה על קיבולת משותפת עם מגבלות שנקראות [[Quota]]s. ב-Bedrock העיקריות סופרות **טוקנים לדקה** לכל מודל, לכל חשבון ולכל Region. רואים אותן בקונסול של **Service Quotas** תחת השירות "Amazon Bedrock". כשהאפליקציה שלך עוברת quota, AWS דוחה את הבקשות העודפות עם `ThrottlingException` (HTTP 429). זה [[Throttling]].' },
        { t: 'list', en: ['Throttling is not a bug in your code and not an outage. It is a limit doing its job.', 'Default quotas are not the same for everyone. The docs say they can differ per account, and new accounts often start low.', 'You can ask for an increase. AWS gives priority to customers whose traffic already uses their current quota, so "we might need it one day" is a weak request.', 'Your code must expect throttling and retry politely (module 3 shows how).'], he: ['Throttling הוא לא באג בקוד שלך ולא תקלה. זו מגבלה שעושה את העבודה שלה.', 'Quotas ברירת מחדל לא זהות לכולם. התיעוד אומר שהן יכולות להיות שונות בין חשבונות, וחשבונות חדשים מתחילים לעיתים קרובות נמוך.', 'אפשר לבקש העלאה. AWS נותנת עדיפות ללקוחות שהתעבורה שלהם כבר מנצלת את ה-quota הנוכחית, כך ש"אולי נצטרך יום אחד" היא בקשה חלשה.', 'הקוד שלך חייב לצפות ל-throttling ולנסות שוב בנימוס (מודול 3 מראה איך).'] },
        { t: 'quiz', q: { en: 'Your chatbot launches. At 09:00, when everyone logs in, a share of the requests fail with HTTP 429 `ThrottlingException`. At 11:00 all is fine again. What is going on?', he: 'הצ׳אטבוט שלך עולה לאוויר. ב-09:00, כשכולם מתחברים, חלק מהבקשות נכשלות עם HTTP 429 `ThrottlingException`. ב-11:00 הכול שוב בסדר. מה קורה?' },
          options: { en: ['The IAM role loses its permissions under load', 'The morning peak goes over the tokens-per-minute quota for that model in that Region', 'The model is retrained every morning', 'The API key expires at 09:00'], he: ['ה-IAM role מאבד הרשאות בעומס', 'שיא הבוקר עובר את ה-quota של טוקנים לדקה למודל הזה ב-Region הזה', 'המודל מאומן מחדש כל בוקר', 'ה-API key פג ב-09:00'] },
          answer: 1, explain: { en: '429 means "too much, too fast", and it comes and goes with load. A permission problem would be a 403 AccessDeniedException and would fail all the time, not only at peak. The fixes: retries with backoff, spreading load, and a quota increase supported by your real traffic numbers.', he: '429 אומר "יותר מדי, מהר מדי", והוא בא והולך עם העומס. בעיית הרשאות הייתה 403 AccessDeniedException והייתה נכשלת כל הזמן, לא רק בשיא. הפתרונות: retries עם backoff, פיזור עומס, ובקשה להעלאת quota שנתמכת במספרי התעבורה האמיתיים שלך.' } },
        { t: 'match', prompt: { en: 'Match the need to the service.', he: 'התאם את הצורך לשירות.' }, pairs: [
          { a: { en: 'Store 10,000 PDFs for a knowledge base', he: 'לאחסן 10,000 קובצי PDF ל-knowledge base' }, b: 'S3' },
          { a: { en: 'Run the code of the tool "get order status"', he: 'להריץ את הקוד של הכלי "get order status"' }, b: 'Lambda' },
          { a: { en: 'Alarm when model latency gets too high', he: 'התראה כש-latency של המודל גבוה מדי' }, b: 'CloudWatch' },
          { a: { en: 'Prove which role called the model', he: 'להוכיח איזה role קרא למודל' }, b: 'CloudTrail' },
          { a: { en: 'Keep model traffic off the public internet', he: 'להשאיר תעבורת מודלים מחוץ לאינטרנט הציבורי' }, b: 'PrivateLink' },
          { a: { en: 'Encrypt with a key that the company can switch off', he: 'להצפין עם מפתח שהחברה יכולה לכבות' }, b: 'KMS' }
        ] },
        { t: 'reveal', q: { en: 'Interview question: "What is the difference between CloudWatch, CloudTrail and model invocation logging in Bedrock?"', he: 'שאלת ראיון: "מה ההבדל בין CloudWatch, CloudTrail ו-model invocation logging ב-Bedrock?"' },
          a: { en: 'CloudWatch metrics are numbers about operation: how many invocations, tokens, latency, errors and throttles. I use them for dashboards and alarms. CloudTrail is the audit log: which principal called which API and when. It records that a model was invoked and its ID, but not the prompt. Model invocation logging is the only one that stores the content, the full request and response. It is off by default, set per Region, and writes to CloudWatch Logs or S3. Because it holds user data, I treat its destination as sensitive and restrict who can read it.', he: 'Metrics של CloudWatch הם מספרים על התפעול: כמה invocations, טוקנים, latency, שגיאות ו-throttles. משתמשים בהם לדשבורדים ול-alarms. CloudTrail הוא יומן הביקורת: איזה principal קרא לאיזה API ומתי. הוא רושם שמודל הופעל ואת המזהה שלו, אבל לא את הפרומפט. Model invocation logging הוא היחיד ששומר את התוכן, הבקשה והתשובה המלאות. הוא כבוי כברירת מחדל, מוגדר לכל Region, וכותב ל-CloudWatch Logs או ל-S3. מכיוון שהוא מחזיק מידע של משתמשים, מתייחסים ליעד שלו כרגיש ומגבילים מי יכול לקרוא אותו.' } }
      ]
    },
    {
      id: 'm02l5', minutes: 10,
      title: { en: 'Jargon and scenarios workout', he: 'אימון ז׳רגון ותרחישים' },
      blocks: [
        { t: 'p', en: 'You now have the AWS vocabulary that every GenAI project uses. This lesson has no new material. It checks that you can use the words under pressure: in a design meeting, in a debugging session, in an interview.', he: 'עכשיו יש לך את אוצר המילים של AWS שכל פרויקט GenAI משתמש בו. בשיעור הזה אין חומר חדש. הוא בודק שאתה יכול להשתמש במילים תחת לחץ: בישיבת תכנון, בסשן דיבוג, בראיון.' },
        { t: 'match', prompt: { en: 'Match the word to its meaning.', he: 'התאם את המילה למשמעות שלה.' }, pairs: [
          { a: 'Principal', b: { en: 'The identity that makes the call', he: 'הזהות שמבצעת את הקריאה' } },
          { a: 'Trust policy', b: { en: 'Says who may assume a role', he: 'אומרת מי רשאי לקחת role' } },
          { a: 'SCP', b: { en: 'A limit from the organization on a whole account', he: 'מגבלה מהארגון על חשבון שלם' } },
          { a: 'ARN', b: { en: 'The full unique name of a resource', he: 'השם המלא והייחודי של משאב' } },
          { a: 'Profile', b: { en: 'A named set of CLI and SDK settings', he: 'קבוצת הגדרות עם שם ל-CLI ול-SDK' } },
          { a: 'Quota', b: { en: 'A limit per account and Region', he: 'מגבלה לכל חשבון ו-Region' } }
        ] },
        { t: 'match', prompt: { en: 'Match the symptom to the most likely cause.', he: 'התאם את הסימפטום לסיבה הכי סבירה.' }, pairs: [
          { a: { en: 'HTTP 403 on every call, from the first one', he: 'HTTP 403 על כל קריאה, מהראשונה' }, b: { en: 'The role has no Allow for this action or ARN', he: 'ל-role אין Allow לפעולה או ל-ARN הזה' } },
          { a: { en: 'HTTP 429 only at busy hours', he: 'HTTP 429 רק בשעות עמוסות' }, b: { en: 'The tokens-per-minute quota is exceeded', he: 'עברו את ה-quota של טוקנים לדקה' } },
          { a: { en: '"Resource not found" for something you see in the console', he: '"Resource not found" על משהו שרואים בקונסול' }, b: { en: 'The code and the console use different Regions', he: 'הקוד והקונסול משתמשים ב-Regions שונים' } },
          { a: { en: 'The script runs as an unexpected identity', he: 'הסקריפט רץ בתור זהות לא צפויה' }, b: { en: 'Old key variables in the environment win over the profile', he: 'משתני מפתחות ישנים בסביבה מנצחים את ה-profile' } },
          { a: { en: 'Works on the laptop, 403 in Lambda', he: 'עובד על הלפטופ, 403 ב-Lambda' }, b: { en: 'The execution role is a different principal with fewer permissions', he: 'ה-execution role הוא principal אחר עם פחות הרשאות' } }
        ] },
        { t: 'quiz', q: { en: 'A new teammate asks for "an access key so I can start working with Bedrock". What is the best answer?', he: 'חבר צוות חדש מבקש "access key כדי שאוכל להתחיל לעבוד עם Bedrock". מה התשובה הכי טובה?' },
          options: { en: ['Set up an SSO profile with `aws configure sso`, then log in and you get temporary credentials for a developer role', 'Here is my key, we can share it', 'Create an IAM user with AdministratorAccess for yourself', 'Use the root user of the account, it can do everything'], he: ['הגדר profile של SSO עם `aws configure sso`, אחר כך התחבר ותקבל credentials זמניים ל-role של מפתח', 'הנה המפתח שלי, אפשר לחלוק אותו', 'צור לעצמך IAM user עם AdministratorAccess', 'השתמש ב-root user של החשבון, הוא יכול הכול'] },
          answer: 0, explain: { en: 'People get temporary credentials through IAM Identity Center. Shared keys destroy the audit trail (CloudTrail would show one identity for two people), and long-term admin keys are the most dangerous secret a team can have.', he: 'אנשים מקבלים credentials זמניים דרך IAM Identity Center. מפתחות משותפים הורסים את יומן הביקורת (CloudTrail יראה זהות אחת לשני אנשים), ומפתחות admin ארוכי-טווח הם הסוד הכי מסוכן שיכול להיות לצוות.' } },
        { t: 'quiz', q: { en: 'You must give an agent\'s role access to one knowledge base and one model. A colleague suggests `"Action": "bedrock:*", "Resource": "*"` "to save time". What is the strongest argument against it?', he: 'אתה צריך לתת ל-role של סוכן גישה ל-knowledge base אחד ולמודל אחד. עמית מציע `"Action": "bedrock:*", "Resource": "*"` "כדי לחסוך זמן". מה הטיעון הכי חזק נגד?' },
          options: { en: ['Wildcards make IAM evaluation slower', 'If the agent is tricked or has a bug, it can do anything in Bedrock with that role: read other knowledge bases, delete guardrails, call any model', 'AWS charges more for wide policies', 'A policy with a wildcard is not valid JSON'], he: ['wildcards מאטים את ההערכה של IAM', 'אם הסוכן מרומה או שיש בו באג, הוא יכול לעשות הכול ב-Bedrock עם ה-role הזה: לקרוא knowledge bases אחרים, למחוק guardrails, לקרוא לכל מודל', 'AWS גובה יותר על policies רחבות', 'policy עם wildcard היא לא JSON תקין'] },
          answer: 1, explain: { en: 'Least privilege limits the damage when something goes wrong, and with agents something can go wrong through the prompt itself. IAM is free and wildcards are valid. The cost of a wide policy is risk, not money or speed.', he: 'Least privilege מגביל את הנזק כשמשהו משתבש, ואצל סוכנים משהו יכול להשתבש דרך הפרומפט עצמו. IAM חינמי ו-wildcards תקינים. המחיר של policy רחבה הוא סיכון, לא כסף או מהירות.' } },
        { t: 'quiz', q: { en: 'A batch job in Bedrock reads prompts from `s3://acme-batch/input/` and fails at once with an access error. Your own user can read the bucket without a problem. What is the likely cause?', he: 'עבודת batch ב-Bedrock קוראת פרומפטים מ-`s3://acme-batch/input/` ונכשלת מיד עם שגיאת גישה. המשתמש שלך יכול לקרוא את ה-bucket בלי בעיה. מה הסיבה הסבירה?' },
          options: { en: ['S3 does not work with Bedrock', 'The bucket is in the same Region as the job', 'The job runs with a service role, and that role has no permission to the bucket (or to its KMS key)', 'Batch jobs need an API key'], he: ['S3 לא עובד עם Bedrock', 'ה-bucket באותו Region כמו העבודה', 'העבודה רצה עם service role, ול-role הזה אין הרשאה ל-bucket (או למפתח ה-KMS שלו)', 'עבודות batch צריכות API key'] },
          answer: 2, explain: { en: 'Again: who is the principal? Not you. The job runs as the service role that you gave it. That role needs read access to the input, write access to the output, and permission to use the key if the bucket is encrypted with a customer managed key.', he: 'שוב: מי ה-principal? לא אתה. העבודה רצה בתור ה-service role שנתת לה. ה-role הזה צריך גישת קריאה לקלט, גישת כתיבה לפלט, והרשאה להשתמש במפתח אם ה-bucket מוצפן במפתח בניהול הלקוח.' } },
        { t: 'quiz', q: { en: 'Which sentence about Regions is correct?', he: 'איזה משפט על Regions נכון?' },
          options: { en: ['An IAM role must be created again in every Region', 'A quota increase in us-east-1 also applies in us-west-2', 'Every Bedrock model is available in every Region', 'A guardrail created in us-east-1 cannot be used by a call sent to us-west-2'], he: ['צריך ליצור IAM role מחדש בכל Region', 'העלאת quota ב-us-east-1 חלה גם ב-us-west-2', 'כל מודל של Bedrock זמין בכל Region', 'guardrail שנוצר ב-us-east-1 לא יכול לשמש קריאה שנשלחה ל-us-west-2'] },
          answer: 3, explain: { en: 'Bedrock resources are regional, so the guardrail exists only where it was created. IAM is the exception: it is global, and a role works in every Region. Quotas and model availability are per Region.', he: 'משאבי Bedrock הם אזוריים, ולכן ה-guardrail קיים רק במקום שבו נוצר. IAM הוא היוצא מן הכלל: הוא גלובלי, ו-role עובד בכל Region. Quotas וזמינות מודלים הם לכל Region.' } },
        { t: 'order', prompt: { en: 'Your code runs `client.converse(...)`. Put what happens in order.', he: 'הקוד שלך מריץ `client.converse(...)`. סדר את מה שקורה.' }, items: { en: ['The SDK finds credentials (environment, profile or attached role)', 'The SDK signs the request with SigV4', 'The request reaches the Bedrock endpoint of the chosen Region', 'IAM checks: may this principal do this action on this resource?', 'Bedrock checks the quota, and the model runs', 'CloudTrail records who made the call'], he: ['ה-SDK מוצא credentials (סביבה, profile או role מוצמד)', 'ה-SDK חותם על הבקשה עם SigV4', 'הבקשה מגיעה ל-endpoint של Bedrock ב-Region שנבחר', 'IAM בודק: האם ל-principal הזה מותר לעשות את הפעולה הזו על המשאב הזה?', 'Bedrock בודק את ה-quota, והמודל רץ', 'CloudTrail רושם מי ביצע את הקריאה'] },
          explain: { en: 'Each step has its own typical failure: "Unable to locate credentials" (step 1), a wrong Region (step 3), AccessDeniedException (step 4), ThrottlingException (step 5). When you know the path, the error tells you where on the path you are.', he: 'לכל שלב יש כישלון אופייני משלו: "Unable to locate credentials" (שלב 1), Region שגוי (שלב 3), AccessDeniedException (שלב 4), ThrottlingException (שלב 5). כשמכירים את המסלול, השגיאה אומרת לך איפה אתה נמצא עליו.' } },
        { t: 'reveal', q: { en: 'Interview question: "Walk me through how you would give a new GenAI service access to Bedrock in production."', he: 'שאלת ראיון: "תאר לי איך היית נותן לשירות GenAI חדש גישה ל-Bedrock ב-production."' },
          a: { en: 'I create a dedicated IAM role for the service, with a trust policy that lets only its compute (for example Lambda) assume it. The permissions policy allows only the two inference actions, `bedrock:InvokeModel` and `bedrock:InvokeModelWithResponseStream`, and only on the ARNs of the models or inference profiles the service uses, in the Regions it uses. If it needs other resources, such as one knowledge base or one bucket, I add exactly those. There are no stored keys: the SDK takes temporary credentials from the role. I check that organization rules (SCPs) allow the Regions involved. Then I turn on the observability I will need later: CloudWatch alarms on errors and throttles, and model invocation logging to a restricted destination if the data policy allows it.', he: 'יוצרים IAM role ייעודי לשירות, עם trust policy שמרשה רק לסביבת הריצה שלו (למשל Lambda) לקחת אותו. ה-permissions policy מרשה רק את שתי פעולות ה-inference, `bedrock:InvokeModel` ו-`bedrock:InvokeModelWithResponseStream`, ורק על ה-ARNs של המודלים או ה-inference profiles שהשירות משתמש בהם, ב-Regions שהוא משתמש בהם. אם הוא צריך משאבים אחרים, כמו knowledge base אחד או bucket אחד, מוסיפים בדיוק אותם. אין מפתחות שמורים: ה-SDK לוקח credentials זמניים מה-role. בודקים שכללי הארגון (SCPs) מרשים את ה-Regions המעורבים. ואז מדליקים את ה-observability שנצטרך אחר כך: alarms של CloudWatch על שגיאות ו-throttles, ו-model invocation logging ליעד מוגבל אם מדיניות המידע מרשה.' } },
        { t: 'reveal', q: { en: 'Your manager asks: "Why did the demo work for you all week and then fail in front of the customer with AccessDenied?" Give the three most likely explanations.', he: 'המנהל שלך שואל: "למה הדמו עבד אצלך כל השבוע ואז נכשל מול הלקוח עם AccessDenied?" תן את שלושת ההסברים הכי סבירים.' },
          a: { en: 'One: a different identity. All week it ran with my wide developer role, and in the demo it ran with the application role or in the customer\'s account, which has fewer permissions. Two: a different place. The demo environment used another Region or another account, where the model or the resource is not allowed, or an organization rule (SCP) blocks it. Three: a different code path. The demo touched something that my tests never did, for example streaming, which needs its own IAM action, or a model from a provider that needs Marketplace permissions on first use. In all three cases the error message names the principal, the action and the resource, so the first step is to read it fully.', he: 'אחד: זהות אחרת. כל השבוע זה רץ עם ה-role הרחב שלי כמפתח, ובדמו זה רץ עם ה-role של האפליקציה או בחשבון של הלקוח, שיש לו פחות הרשאות. שתיים: מקום אחר. סביבת הדמו השתמשה ב-Region אחר או בחשבון אחר, שבו המודל או המשאב לא מורשים, או שכלל ארגוני (SCP) חוסם אותם. שלוש: מסלול קוד אחר. הדמו נגע במשהו שהבדיקות שלי מעולם לא נגעו בו, למשל streaming, שצריך פעולת IAM משלו, או מודל של ספק שצריך הרשאות Marketplace בשימוש הראשון. בשלושת המקרים הודעת השגיאה מציינת את ה-principal, הפעולה והמשאב, אז הצעד הראשון הוא לקרוא אותה עד הסוף.' } },
        { t: 'task', title: { en: 'After you land: in a real AWS account', he: 'אחרי הנחיתה: בחשבון AWS אמיתי' }, steps: { en: ['Install the AWS CLI and run `aws configure sso` (or `aws configure` on a personal account). Then run `aws sts get-caller-identity` and read the three fields.', 'Create a budget alert in AWS Budgets before you call any model.', 'Run `aws bedrock list-foundation-models --region us-east-1` and `aws bedrock list-inference-profiles --region us-east-1`. Notice the difference between the two lists.', 'In the IAM console, open the role you are logged in with and read its policies. Find the statement that lets you call Bedrock.', 'Write a policy that allows the two inference actions on one model only. Attach it to a new test role and try to call a different model. Read the AccessDeniedException you get, word by word.', 'In the Bedrock console, open **Settings** and look at **Model invocation logging**. Decide where your logs should go before you turn it on.', 'Open the Service Quotas console, choose "Amazon Bedrock", and find the tokens-per-minute quota of the model you plan to use.'], he: ['התקן את ה-AWS CLI והרץ `aws configure sso` (או `aws configure` בחשבון אישי). אחר כך הרץ `aws sts get-caller-identity` וקרא את שלושת השדות.', 'צור התראת תקציב ב-AWS Budgets לפני שאתה קורא למודל כלשהו.', 'הרץ `aws bedrock list-foundation-models --region us-east-1` ו-`aws bedrock list-inference-profiles --region us-east-1`. שים לב להבדל בין שתי הרשימות.', 'בקונסול של IAM, פתח את ה-role שאיתו אתה מחובר וקרא את ה-policies שלו. מצא את ה-statement שמרשה לך לקרוא ל-Bedrock.', 'כתוב policy שמרשה את שתי פעולות ה-inference על מודל אחד בלבד. הצמד אותה ל-role בדיקה חדש ונסה לקרוא למודל אחר. קרא את ה-AccessDeniedException שתקבל, מילה במילה.', 'בקונסול של Bedrock, פתח את **Settings** והסתכל על **Model invocation logging**. החלט לאן הלוגים שלך צריכים ללכת לפני שאתה מדליק.', 'פתח את הקונסול של Service Quotas, בחר "Amazon Bedrock", ומצא את ה-quota של טוקנים לדקה של המודל שאתה מתכנן להשתמש בו.'] } }
      ]
    }
  ]
});
